        // GET: ReportQC
        [SessionExpireFilterAttribute]
        [ValidateInput(false)]
        public ActionResult Index()
        {
            try
            {
                short teamMemerRowId = Convert.ToInt16(Session["TeamMemberRowID"]);
                string Designation = Session["Designation"].ToString();

                //DataEntry Manager
                if (Designation == "Manager Quality Check")
                {
                    ViewBag.RWQCDashboard = "Report Writer QC Manager Dashboard!";
                    ViewBag.RWQCManagerDashboard = repoDashboardRWQC.GetRWQCManagerDashBoardInfo(teamMemerRowId, Designation);
                }

                //DataEntry TeamLeader               
                if (Designation == "Team Leader Quality Check")
                {
                    ViewBag.RWQCDashboard = "Report Writer QC TeamLeader Dashboard!";
                    ViewBag.RWQCTeamLeaderDashboard = repoDashboardRWQC.GetRWQCTeamLeaderDashBoardInfo(teamMemerRowId, Designation);
                }

                if (Designation == "Team Leader Quality Check 2")
                {
                    ViewBag.RWQCDashboard = "Report Writer QC TeamLeader Dashboard!";
                    ViewBag.RWQCTeamLeaderDashboard2 = repoDashboardRWQC.GetRWQCTeamLeader2DashBoardInfo(teamMemerRowId, Designation);
                }

                //DataEntry Team Member-DE-Scan               
                if (Designation == "Team Member Quality Check")
                {
                    if (teamMemerRowId == 1181)
                    {
                        //--New Code For Auto Report Generate
                        int page = 1;
                        int pageSize = 10;

                        DashboardRWQCListViewModel model = new DashboardRWQCListViewModel();
                        string CaseStatus = "Final";
                        string Statusid = "";
                        if (CaseStatus == "Final")
                        {
                            Statusid = "28";
                        }

                        model = repoDashboardRWQC.GetCandidateListForReportQCTeamMember1(1, 10, "", "desc", "", CaseStatus, Statusid, teamMemerRowId, 0, "", "", 0, false);

                        var companyRefNos = model.DashboardDetailsRWQC
                            .Where(x => x.AutoReportGenerate == 1)
                            .Select(x => x.CompanyRefNo)
                            .Distinct()
                            .ToArray();

                        if (companyRefNos.Any())
                        {
                            AutoGenerateReport(companyRefNos, "Final");
                        }

                    }

                    ViewBag.RWQCDashboard = "Report Writer QC TeamMember Scanner Dashboard!";
                    ViewBag.RWQCTeamMemberDashboard = repoDashboardRWQC.GetRQQCTeamMemberDashBoardInfo(teamMemerRowId, Designation);

                    ViewBag.RWQCTeamMemberQCDashboard = repoDashboardRWQC.GetRQQCTeamMemberQCDashBoardInfo(1071, Designation);
                }


                if (Designation == "Team Member Quality Check 2")
                {
                    ViewBag.RWQCDashboard = "Report Writer QC TeamMember Scanner Dashboard!";
                    ViewBag.RWQCTeamMemberQCDashboard = repoDashboardRWQC.GetRQQCTeamMemberQCDashBoardInfo(teamMemerRowId, Designation);
                }

            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            return View();
        }

