        public ActionResult AutoGenerateReportSingle(string companyRefNo, string RptGenerateType = "Final")
        {
            ClientCustomize cc = new ClientCustomize();
            string UploadReportList = "";
            byte[] byteArray = null;
            string ImgName = "";

            try
            {
                string CompanyRefNo = companyRefNo.ToString();
                //var Infotbl = cc.GetpersonaldatafromCompanyRefNo(CompanyRefNo);
                var Infotbl = cc.GetpersonaldatafromCompanyRefNoNew(CompanyRefNo);
                if (Infotbl.Rows.Count > 0)
                {
                    int PersonalRowid = Convert.ToInt32(Infotbl.Rows[0]["PersonalRowID"]);
                    int intClientRowId = Convert.ToInt32(Infotbl.Rows[0]["ClientRowID"]);
                                        
                    if (RptGenerateType == "Interim")
                    {
                        cc.UpdateCheckStatusBulkPersonalRowIdInterim(PersonalRowid, Convert.ToInt32(Session["TeamMemberRowID"]));
                    }
                    else
                    {
                        cc.UpdateCheckstatusbulkPersonalrowId(PersonalRowid, Convert.ToInt32(Session["TeamMemberRowID"]));
                    }

                    string html;                    
                    //if (CompanyRefNo.StartsWith("FAPL"))
                    //{
                    //    DataTable dt_Liveness = new DataTable();
                    //    dt_Liveness = cc.GetPersonalRowID(CompanyRefNo);
                    //    int personal = 0;
                    //    int Mainpersonal = 0;
                    //    if (dt_Liveness.Rows.Count > 0)
                    //    {
                    //        personal = Convert.ToInt32(dt_Liveness.Rows[0]["TempPersonalRowID"].ToString());
                    //        Mainpersonal = Convert.ToInt32(dt_Liveness.Rows[0]["PersonalRowID"].ToString());
                    //    }
                    //    html = BulkRenderLivenessViewToString(ControllerContext, "~/views/Verification/ReportMain.cshtml", personal, Mainpersonal, true);
                    //}
                    //else
                    //{
                        html = BulkRenderViewToString(ControllerContext, "~/views/Verification/ReportMain.cshtml", PersonalRowid, true, RptGenerateType);
                    //}

                    string IronKey = System.Configuration.ConfigurationManager.AppSettings["IronKey"].ToString();
                    IronPdf.License.LicenseKey = IronKey;

                    IronPdf.PdfDocument PDF;

                    bool isChrome = ((intClientRowId == 75) || (intClientRowId == 860) || (intClientRowId == 446) || (intClientRowId == 944) || (intClientRowId == 1128)
                        || (intClientRowId == 1130) || (intClientRowId == 990) || (intClientRowId == 762) || (intClientRowId == 317) || (intClientRowId == 327)
                        || (intClientRowId == 1160) || (intClientRowId == 950) || (intClientRowId == 885) || (intClientRowId == 1218)
                        || (intClientRowId == 1315) || (intClientRowId == 787) || (intClientRowId == 392) || (intClientRowId == 1340) || (intClientRowId == 1557)
                        || (intClientRowId == 932) || (intClientRowId == 876) || (intClientRowId == 1362) || (intClientRowId == 1370));

                    if (isChrome)
                    {
                        var renderer = new IronPdf.ChromePdfRenderer();
                        if (intClientRowId == 1218)
                        {
                            renderer.RenderingOptions.SetCustomPaperSizeinPixelsOrPoints(700, 1050);
                        }
                        else
                        {
                            renderer.RenderingOptions.PaperSize = IronPdf.Rendering.PdfPaperSize.Custom;
                        }
                        renderer.RenderingOptions.MarginTop = 3;
                        renderer.RenderingOptions.MarginLeft = 5;
                        renderer.RenderingOptions.MarginRight = 5;
                        renderer.RenderingOptions.MarginBottom = 3;

                        PDF = renderer.RenderHtmlAsPdf(html);
                    }
                    else
                    {
                        var renderer = new IronPdf.HtmlToPdf();
                        renderer.RenderingOptions.PaperSize = IronPdf.Rendering.PdfPaperSize.A4;

                        renderer.RenderingOptions.MarginTop = 3;
                        renderer.RenderingOptions.MarginLeft = 5;
                        renderer.RenderingOptions.MarginRight = 5;
                        renderer.RenderingOptions.MarginBottom = 3;

                        PDF = renderer.RenderHtmlAsPdf(html);
                    }
                                        
                    //if (intClientRowId == 268)
                    //{
                    //    PDF.CompressImages(95, true);

                    //    // Option 1 - good balance
                    //    //PDF.CompressImages(90, false);

                    //    // Option 2 - better quality
                    //    //PDF.CompressImages(95, false);

                    //    // Option 3 - maximum image quality
                    //    //PDF.CompressImages(100, false);
                    //}

                    string FinalColorOfCase = "";
                    DataTable dtColorvalidation = new DataTable();
                    dtColorvalidation = cc.CaseColorCodeForReport(PersonalRowid);

                    DataTable bcciColorvalidation = new DataTable();
                    if (intClientRowId == 1692)
                    {
                        bcciColorvalidation = cc.GetBCCIReportColor(PersonalRowid);
                    }

                    if (bcciColorvalidation.Rows.Count > 0 && intClientRowId == 1692)
                    {
                        FinalColorOfCase = bcciColorvalidation.Rows[0]["FinalColor"].ToString();
                    }
                    else if (dtColorvalidation.Rows.Count > 0)
                    {
                        FinalColorOfCase = dtColorvalidation.Rows[0]["colorname"].ToString();
                    }
                    else
                    {
                        FinalColorOfCase = "No-Color";
                    }

                    // Convert to byte array
                    byteArray = PDF.BinaryData;

                    string FldPathDoc = string.Empty;
                    FldPathDoc = ConfigurationManager.AppSettings["CandidateReportdoc".Trim().ToLower()].ToString();
                    ImgName = CompanyRefNo.ToString() + ".pdf";
                    string fileSavePath = Server.MapPath(FldPathDoc + ImgName);                    

                    var pdfFilePath = System.IO.Path.Combine(System.IO.Path.GetTempPath(), ImgName);
                    System.IO.File.WriteAllBytes(pdfFilePath, byteArray);

                    using (var fileStream = new FileStream(pdfFilePath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite))
                    {
                        var uploadedFile = new CustomHttpPostedFileBase(pdfFilePath);

                        // Create FormCollection Object
                        FormCollection form = new FormCollection();
                        form.Add("ddlColor", FinalColorOfCase);
                        //form.Add("ddlReportType", "Final");
                        form.Add("ddlReportType", RptGenerateType);
                        form.Add("SubCheckRowID", "0");
                        form.Add("ClientRowID", intClientRowId.ToString());

                        // Call upload function
                        UploadReportPDFFileBYRWTM(uploadedFile, null, form);
                                                
                        if (RptGenerateType == "Interim")
                        {
                            cc.UploadReportDetails(PersonalRowid, ImgName, "Completed", "");
                        }
                        else
                        {
                            cc.UploadReportDetails(PersonalRowid, ImgName, "", "Completed");
                        }

                        UploadReportList = UploadReportList + "," + PersonalRowid.ToString();

                    }

                    #region Case Action history save
                    clsCommonMethods.AddCaseActionHistory(PersonalRowid, "AutoGenerateReportSingle", "AutoGenerateReportSingle_By_Function_" + RptGenerateType);
                    #endregion

                    if (System.IO.File.Exists(pdfFilePath))
                    {
                        System.IO.File.Delete(pdfFilePath);
                    }

                }

            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }

            return File(byteArray, "application/pdf", ImgName);
        }

        public string AutoGenerateReport(string[] kk, string RptGenerateType = "Final")
        {
            ClientCustomize cc = new ClientCustomize();
            string UploadReportList = "";

            try
            {
                foreach (var RefId in kk)
                {
                    try
                    {
                        string CompanyRefNo = RefId.ToString();
                        //var Infotbl = cc.GetpersonaldatafromCompanyRefNo(CompanyRefNo);
                        var Infotbl = cc.GetpersonaldatafromCompanyRefNoNew(CompanyRefNo);
                        if (Infotbl.Rows.Count > 0)
                        {
                            int PersonalRowid = Convert.ToInt32(Infotbl.Rows[0]["PersonalRowID"]);
                            int intClientRowId = Convert.ToInt32(Infotbl.Rows[0]["ClientRowID"]);

                            if (RptGenerateType == "Interim")
                            {
                                cc.UpdateCheckStatusBulkPersonalRowIdInterim(PersonalRowid, Convert.ToInt32(Session["TeamMemberRowID"]));
                            }
                            else
                            {
                                cc.UpdateCheckstatusbulkPersonalrowId(PersonalRowid, Convert.ToInt32(Session["TeamMemberRowID"]));
                            }

                            string html;
                            html = BulkRenderViewToString(ControllerContext, "~/views/Verification/ReportMain.cshtml", PersonalRowid, true, "Final");

                            string IronKey = System.Configuration.ConfigurationManager.AppSettings["IronKey"].ToString();
                            IronPdf.License.LicenseKey = IronKey;

                            IronPdf.PdfDocument PDF;

                            bool isChrome = ((intClientRowId == 75) || (intClientRowId == 860) || (intClientRowId == 446) || (intClientRowId == 944) || (intClientRowId == 1128)
                                || (intClientRowId == 1130) || (intClientRowId == 990) || (intClientRowId == 762) || (intClientRowId == 317) || (intClientRowId == 327)
                                || (intClientRowId == 1160) || (intClientRowId == 950) || (intClientRowId == 885) || (intClientRowId == 1218)
                                || (intClientRowId == 1315) || (intClientRowId == 787) || (intClientRowId == 392) || (intClientRowId == 1340) || (intClientRowId == 1557)
                                || (intClientRowId == 932) || (intClientRowId == 876) || (intClientRowId == 1362) || (intClientRowId == 1370));

                            if (isChrome)
                            {
                                var renderer = new IronPdf.ChromePdfRenderer();
                                if (intClientRowId == 1218)
                                {
                                    renderer.RenderingOptions.SetCustomPaperSizeinPixelsOrPoints(700, 1050);
                                }
                                else
                                {
                                    renderer.RenderingOptions.PaperSize = IronPdf.Rendering.PdfPaperSize.Custom;
                                }
                                renderer.RenderingOptions.MarginTop = 3;
                                renderer.RenderingOptions.MarginLeft = 5;
                                renderer.RenderingOptions.MarginRight = 5;
                                renderer.RenderingOptions.MarginBottom = 3;

                                PDF = renderer.RenderHtmlAsPdf(html);
                            }
                            else
                            {
                                var renderer = new IronPdf.HtmlToPdf();
                                renderer.RenderingOptions.PaperSize = IronPdf.Rendering.PdfPaperSize.A4;

                                renderer.RenderingOptions.MarginTop = 3;
                                renderer.RenderingOptions.MarginLeft = 5;
                                renderer.RenderingOptions.MarginRight = 5;
                                renderer.RenderingOptions.MarginBottom = 3;

                                PDF = renderer.RenderHtmlAsPdf(html);

                            }

                            string FinalColorOfCase = "";
                            DataTable dtColorvalidation = new DataTable();
                            dtColorvalidation = cc.CaseColorCodeForReport(PersonalRowid);

                            DataTable bcciColorvalidation = new DataTable();
                            if (intClientRowId == 1692)
                            {
                                bcciColorvalidation = cc.GetBCCIReportColor(PersonalRowid);
                            }

                            if (bcciColorvalidation.Rows.Count > 0 && intClientRowId == 1692)
                            {
                                FinalColorOfCase = bcciColorvalidation.Rows[0]["FinalColor"].ToString();
                            }
                            else if (dtColorvalidation.Rows.Count > 0)
                            {
                                FinalColorOfCase = dtColorvalidation.Rows[0]["colorname"].ToString();
                            }
                            else
                            {
                                FinalColorOfCase = "No-Color";
                            }

                            // Convert to byte array
                            var byteArray = PDF.BinaryData;

                            string FldPathDoc = string.Empty;
                            FldPathDoc = ConfigurationManager.AppSettings["CandidateReportdoc".Trim().ToLower()].ToString();
                            string ImgName = CompanyRefNo.ToString() + ".pdf";
                            string fileSavePath = Server.MapPath(FldPathDoc + ImgName);
                            
                            var pdfFilePath = System.IO.Path.Combine(System.IO.Path.GetTempPath(), ImgName);
                            System.IO.File.WriteAllBytes(pdfFilePath, byteArray);

                            using (var fileStream = new FileStream(pdfFilePath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite))
                            {
                                //--Comment for Test                                
                                var uploadedFile = new CustomHttpPostedFileBase(pdfFilePath);

                                // Create FormCollection Object
                                FormCollection form = new FormCollection();
                                form.Add("ddlColor", FinalColorOfCase);
                                //form.Add("ddlReportType", "Final");
                                form.Add("ddlReportType", RptGenerateType);
                                form.Add("SubCheckRowID", "0");
                                form.Add("ClientRowID", intClientRowId.ToString());

                                //Call upload function
                                UploadReportPDFFileBYRWTM(uploadedFile, null, form);
                                
                                if (RptGenerateType == "Interim")
                                {
                                    cc.UploadReportDetails(PersonalRowid, ImgName, "Completed", "");
                                }
                                else
                                {
                                    cc.UploadReportDetails(PersonalRowid, ImgName, "", "Completed");
                                }
                                //--Comment for Test

                                UploadReportList = PersonalRowid.ToString();

                            }

                            if (System.IO.File.Exists(pdfFilePath))
                            {
                                System.IO.File.Delete(pdfFilePath);
                            }

                        }

                    }
                    catch (Exception ex)
                    {
                        clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), ex.Message, ex.StackTrace);
                        return UploadReportList;
                    }

                }                
            }
            catch (Exception ex)
            {
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), ex.Message, ex.StackTrace);
                return UploadReportList;
            }

            return UploadReportList;
        }

        public string BulkRenderLivenessViewToString(ControllerContext context, string viewPath, int personalRowid, int Mainpersonal, bool partial = false)
        {
            string result = null;
            try
            {
                DataTable dt = new DataTable();
                DataTable dt1 = new DataTable();
                ClientCustomize cc = new ClientCustomize();
                ReportViewModel model = new ReportViewModel();
                dt = cc.GetLivenessJsonPayload(personalRowid);
                if (dt != null && dt.Rows.Count > 0)
                {
                    model.VideoFileName = dt.Rows[0]["VideofileName"].ToString();
                }
                DataTable dtclient = cc.GetClientRowidBylivePersonalRowid(personalRowid);
                short ClientID = 0;
                if (dtclient.Rows.Count > 0)
                {
                    ClientID = Convert.ToInt16(dtclient.Rows[0]["ClientRowid"]);
                }

                dt1 = cc.getDocumentType(Mainpersonal);

                if (dt1.Rows.Count == 0)
                {
                    string inputVideo = Server.MapPath(ConfigurationManager.AppSettings["candidatevideos"].ToString()) + model.VideoFileName;

                    string outputImage = "";

                    string imagefilname = (Mainpersonal + "_" + model.PersonalName + "_Video_" + DateTime.Now.Ticks + ".jpg").Trim().Replace(" ", "");
                    outputImage = Server.MapPath(ConfigurationManager.AppSettings["provideddocuments"].ToString()) + imagefilname;

                    GetframeFromVideo(Mainpersonal, 890, inputVideo, outputImage, imagefilname);
                }

                model = fnBulkAutoGenerateLivenessReport(personalRowid, Mainpersonal, ClientID, "0", "Liveness");
                model.ReportPart = "liveness";

                //int resolutionDPI = cc.getResolutionForReport(model.ClientRowID);
                //CandidateLivenessPdfLists(personalRowid, resolutionDPI);
                //model.CandidateDocList = repoReportQC.GetCandidateLivenessDocListForReport(personalRowid);


                if (dt != null && dt.Rows.Count > 0)
                {
                    // Extract the JSON string from the first row and first column
                    string jsonString = dt.Rows[0][0].ToString();


                    // Parse the extracted string, not the DataTable object
                    JObject jObject = JObject.Parse(jsonString);

                    string livenessScore = "";
                    string faceConsistencyScore = "";
                    string faceMatchScore = "";
                    string IsFaceMatch = "";
                    string isFaceConsistent = "";
                    string aadharNumber = "";
                    if (!string.IsNullOrWhiteSpace(jsonString))
                    {
                        try
                        {
                            dynamic data = JsonConvert.DeserializeObject(jsonString);

                            livenessScore = data["result"]?["apiResponse"]?["result"]?["livenessScore"]?.ToString() ?? "0"; //data.result.apiResponse.result.livenessScore;

                            faceConsistencyScore = data["result"]?["apiResponse"]?["result"]?["faceConsistencyScore"]?.ToString() ?? "0";  //data.result.apiResponse.result.faceConsistencyScore;

                            IsFaceMatch = data["result"]?["apiResponse"]?["result"]?["isFaceMatch"]?.ToString() ?? "false";     //data.result.apiResponse.result.isFaceMatch;

                            faceMatchScore = data["result"]?["apiResponse"]?["result"]?["faceMatchScore"]?.ToString() ?? "0";  // data.result.apiResponse.result.faceMatchScore;

                            isFaceConsistent = data["result"]?["apiResponse"]?["result"]?["isFaceConsistent"]?.ToString() ?? "false";      //data.result.apiResponse.result.isFaceConsistent;

                            aadharNumber = dt.Rows[0]["aadhaar_number"].ToString();

                            model.livenessScore = Math.Round(Convert.ToDouble(livenessScore)).ToString();
                            model.faceConsistencyScore = Math.Round(Convert.ToDouble(faceConsistencyScore)).ToString();
                            model.faceMatchScore = Math.Round(Convert.ToDouble(faceMatchScore)).ToString();
                            model.IsFaceConsistent = isFaceConsistent;
                            model.IsFaceMatch = IsFaceMatch;
                            model.AadharNumber = aadharNumber;

                        }
                        catch (JsonException ex)
                        {
                            // Handle invalid JSON
                            Console.WriteLine("Failed to parse JSON: " + ex.Message);
                        }
                    }
                    else
                    {
                        Console.WriteLine("JSON payload is empty or null.");
                    }
                }

                // first find the ViewEngine for this view
                ViewEngineResult viewEngineResult = null;
                if (partial)
                    viewEngineResult = ViewEngines.Engines.FindPartialView(context, viewPath);
                else
                    viewEngineResult = ViewEngines.Engines.FindView(context, viewPath, null);

                if (viewEngineResult == null)
                    throw new FileNotFoundException("View cannot be found.");

                // get the view and attach the model to view data
                var view = viewEngineResult.View;
                context.Controller.ViewData.Model = model;

                using (var sw = new StringWriter())
                {
                    var ctx = new ViewContext(context, view, context.Controller.ViewData, context.Controller.TempData, sw);
                    view.Render(ctx, sw);
                    result = sw.ToString();
                }
            }
            catch (Exception Ex)
            {

                throw;
            }


            return result;
        }

