        public ReportViewModel fnBulkAutoGenerateLivenessReport(int PersonalRowID = 0, int MainPersonalRowID = 0, int ClientRowId = 0, string Report_Type = "", string ReportStatus = "", string ReportPart = "", string CaseStatus = "", int SubCheckRowID = 0, string family = "", string CheckFamilyID = "", int IsCheckWiseReport = 0, int CheckFamilyRowID = 0)
        {
            ReportViewModel model = new ReportViewModel();
            ClientCustomize cc = new ClientCustomize();

            #region Main Report Code

            model.IsCheckWiseReport = IsCheckWiseReport;
            model.CheckFamilyRowID = CheckFamilyRowID;

            string CaseType = "";
            if (ClientRowId == 787 || ClientRowId == 3 || ClientRowId == 1057)
            {
                model = repoReportQC.GetCapgeminiReportPersonalInfo(PersonalRowID);
            }
            else if (ClientRowId == 722)
            {
                model = repoReportQC.GetReportPersonalInfo_Genpact(PersonalRowID);
            }
            else if (ClientRowId == 1483 || ClientRowId == 679)
            {
                model = repoReportQC.GetReportLivenessPersonalInfo(PersonalRowID);
            }
            else if (ClientRowId == 860)
            {
                CaseType = cc.GetCaseType(PersonalRowID);

                if (CaseType == "Standard" || CaseType == "")
                {
                    if (SubCheckRowID == 405)
                    {
                        model = repoReportQC.GetReportPersonalInfo_Accenture(PersonalRowID, SubCheckRowID);
                    }
                    else if (SubCheckRowID == 440)
                    {
                        model = repoReportQC.GetReportPersonalInfo_Accenture(PersonalRowID, SubCheckRowID);
                    }
                    else if (SubCheckRowID == 417)
                    {
                        model = repoReportQC.GetReportPersonalInfo_Accenture_CDC(PersonalRowID, SubCheckRowID);
                    }
                    else if (SubCheckRowID == 457)
                    {
                        model = repoReportQC.GetReportPersonalInfo_Accenture_CurrentCompany(PersonalRowID, SubCheckRowID);
                    }
                    else if (SubCheckRowID == 458)
                    {
                        model = repoReportQC.GetReportPersonalInfo_Accenture_CurrentCompany(PersonalRowID, SubCheckRowID);
                    }
                    else if (SubCheckRowID == 412)
                    {
                        model = repoReportQC.GetReportPersonalInfo_Accenture_CurrentEmployementTier3(PersonalRowID, SubCheckRowID);
                    }
                    else if (SubCheckRowID == 409)
                    {
                        model = repoReportQC.GetReportPersonalInfo_Accenture_CurrentEmployementTier3(PersonalRowID, SubCheckRowID);
                    }
                    else
                    {
                        model = repoReportQC.GetReportPersonalInfo(PersonalRowID);
                    }
                }
                else if (CaseType == "Non-Standard-Offline")
                {
                    if (SubCheckRowID == 405 || SubCheckRowID == 440)
                    {
                        model = repoReportQC.GetPersonalInfo_Accenture_CCC(PersonalRowID);
                    }
                    else if (SubCheckRowID == 417)
                    {
                        model = repoReportQC.GetPersonalInfo_Accenture_CDC(PersonalRowID, SubCheckRowID);
                    }
                    else if (SubCheckRowID == 406)
                    {
                        model = repoReportQC.GetPersonalInfo_Accenture_IdCheck(PersonalRowID, SubCheckRowID);
                    }
                    else if (SubCheckRowID == 415)
                    {
                        model = repoReportQC.GetPersonalInfo_Accenture_LegalAgeCheck(PersonalRowID, SubCheckRowID);
                    }
                    else
                    {
                        model = repoReportQC.GetReportPersonalInfo(PersonalRowID);
                    }
                }
                else
                {
                    model = repoReportQC.GetReportPersonalInfo(PersonalRowID);
                }

            }
            else if ((ClientRowId == 1606 || ClientRowId == 684) && ReportStatus == "Liveness")
            {
                model = repoReportQC.GetReportPersonalInfo(MainPersonalRowID);
            }
            else
            {
                model = repoReportQC.GetReportPersonalInfo(PersonalRowID);
            }
            model.SubCheckRowID = SubCheckRowID;
            if (ClientRowId == 576)
            {
                DataTable dtpackage = cc.GetPakegename(model.PersonalRowID);
                model.Location = dtpackage.Rows[0]["packageName"].ToString();
                if (model.Location == "NA")
                {
                    model.Location = "Check wise ";
                }

            }
            if (model.ClientRowID == 268 || model.ClientRowID == 1459)
            {
                string[] A = model.EmploymentId.Split('/');
                if (A.Count() > 2)
                {
                    model.EmploymentType = A[1].ToString();
                    model.Location = A[2].ToString();
                    model.EmploymentId = A[0].ToString();
                }


            }

            int resolutionDPI = cc.getResolutionForReport(model.ClientRowID);
            CandidatePdfLists(MainPersonalRowID, resolutionDPI);
            if (ClientRowId == 310 || ClientRowId == 532 || ClientRowId == 539 || ClientRowId == 568)
            {
                DataTable dtMaruti = new DataTable();
                dtMaruti = cc.GetTMDateOfVerificaton_Check(PersonalRowID);
                try
                {
                    if (dtMaruti.Rows.Count > 0)
                    {
                        model.Checkclosedate = dtMaruti.Rows[0]["dateofVerification"].ToString();
                    }
                }
                catch
                { }
            }
            else
            {
                model.ReportDate = Convert.ToDateTime(DateTime.Now.Date.ToString("dd-MM-yyyy"));
            }

            //CandidatePdfListsNew(id);
            // CandidateCasePdfListsNew(id);
            CandidateCasePdfLists(MainPersonalRowID, resolutionDPI);
            Session["SecritadRefId"] = model.CompanyRefNo;
            ViewBag.CompanyRefNo = model.CompanyRefNo.ToString();

            model.CandidateCaseDocList = repoReportQC.GetCandidateCaseDocListForReport(PersonalRowID);
            if (model.CandidateCaseDocList.Count() > 0)
            {
                if (model.ClientRowID == 231 || model.ClientRowID == 838 || model.ClientRowID == 824 || model.ClientRowID == 832 || model.ClientRowID == 835 || model.ClientRowID == 827 || model.ClientRowID == 1118 || model.ClientRowID == 859)
                {
                    model.CandidatePhoto = model.CandidateCaseDocList.Where(T => T.DocumentType == "Candidate Photo").Select(x => x.DocFile).FirstOrDefault();

                    //model.CandidatePhoto = model.CandidateCaseDocList.Where(T => T.DocumentType == "Candidate Photo").FirstOrDefault().DocFile;
                }
            }
            model.CandidateDocList = repoReportQC.GetCandidateDocListForReport(MainPersonalRowID);
            BindColorCode(model.ClientRowID);
            model.DocPath = ConfigurationManager.AppSettings["provideddocuments"].ToString();
            //model = repoReportQC.GenerateCandidateInterimReportByReportQCTM(PersonalRowID);
            model.ReportPart = ReportPart;
            model.Report_Type = Report_Type;
            model.ReportStatus = ReportStatus;
            if (ClientRowId == 446 || model.ClientRowID == 990 || model.ClientRowID == 1611 || model.ClientRowID == 1539 || model.ClientRowID == 950 || model.ClientRowID == 885 || model.ClientRowID == 392 || model.ClientRowID == 1340 || model.ClientRowID == 932 || model.ClientRowID == 876 || model.ClientRowID == 1362 || model.ClientRowID == 1370)
            {
                Session["Type"] = "";
            }
            Session["id"] = PersonalRowID;
