        [SessionExpireFilterAttribute]
        public ActionResult GetRWQCTeamMemberDashBoardSigleCheck(string Type = "", int page = 1, string sort = "", string sortDir = "desc", string Search = "", short ClientRowID = 0, string CaseStatus = "", string version = "New", string RecievingDate = "", string CompletedDate = "", byte tatHours = 0, string Message = "")
        {
            DashboardRWQCListViewModel model = new DashboardRWQCListViewModel();
            short teamMemberId = Convert.ToInt16(Session["TeamMemberRowID"]);
            try
            {
                Session["CaseStatus"] = CaseStatus;
                int pageSize = clsGlobalCommon.PageSize;
                string Statusid = "";

                if (version == "New")
                {


                    model = repoDashboardRWQC.GetCandidateListForReportQCTeamMembersinglecheck(Type, page, pageSize, sort.ToLower(), sortDir.ToLower(), Search, CaseStatus, Statusid, teamMemberId, ClientRowID, RecievingDate, CompletedDate, tatHours);


                }
                else
                {
                    model = repoDashboardRWQC.GetCandidateListForReportQCTeamMembersinglecheck(Type, page, pageSize, sort.ToLower(), sortDir.ToLower(), Search, CaseStatus, Statusid, teamMemberId, ClientRowID, RecievingDate, CompletedDate, tatHours);
                }

            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }

            //BindClientList();
            BindClientListBaseOnLogin(teamMemberId);
            GetTLMemberForAllocation();
            ViewBag.CaseStatus = CaseStatus;
            ViewBag.version = version;
            return View(model);
        }

