                                    bl.tblDataEntry_OperationInsert(cd);
                                }

                                else
                                    marksModel.Add(d[1].ToString(), d[0].ToString());

                            }
                            cc.UpdateCheckStatus(PersonalRowid, SubCheckid, 1, 37, "Check", Convert.ToInt32(Session["TeamMemberRowID"].ToString()));
                            MasterArtifactMappingsApproving(PersonalRowid, 40, SubCheckid, "", clientRowid);
                            cc.UpdateCheckApproveDate(PersonalRowid, SubCheckid);
