        [HttpPost]
        [ValidateInput(false)]
        public ActionResult GeneratePDFFromHtml(string htmlContent)
        {
            try
            {
                if (string.IsNullOrEmpty(htmlContent))
                {
                    return Json(new { success = false, message = "HTML content is empty" });
                }

                htmlContent = htmlContent.TrimEnd();

                // Configure IronPDF Renderer
                var Renderer = new IronPdf.HtmlToPdf();
                Renderer.RenderingOptions.ViewPortWidth = 1280;
                Renderer.RenderingOptions.Zoom = 100;
                Renderer.RenderingOptions.PaperSize = IronPdf.Rendering.PdfPaperSize.A4;
                Renderer.RenderingOptions.MarginTop = 3;
                Renderer.RenderingOptions.MarginLeft = 5;
                Renderer.RenderingOptions.MarginRight = 5;
                Renderer.RenderingOptions.MarginBottom = 3;

                // Render to PDF
                var PDF = Renderer.RenderHtmlAsPdf(htmlContent);

                // Convert to byte array
                var byteArray = PDF.BinaryData;

                // Create a temp file path
                var pdfFileName = Session["SecritadRefId"].ToString() + ".pdf";
                var pdfFilePath = System.IO.Path.Combine(System.IO.Path.GetTempPath(), pdfFileName);
                System.IO.File.WriteAllBytes(pdfFilePath, byteArray);

                //var fileStream = new FileStream(pdfFilePath, FileMode.Open);
                //var uploadedFile = new CustomHttpPostedFileBase(pdfFilePath);



                // Return PDF as download to browser
                return File(byteArray, "application/pdf", pdfFileName);
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = ex.Message });
            }
        }
