        [HttpPost]
        [SessionExpireFilterAttribute]
        [ValidateAntiForgeryToken]
        [ValidateInput(false)]
        public ActionResult UpdateReportArtifactsDocByRWQCTM(FormCollection form, UploadedDocListForRWQCTMPagedModel model)
        {
            try
            {
                if (ModelState.IsValid)
                {
                    List<MapUploadedDocRWQCTMModel> dMapObj = new List<MapUploadedDocRWQCTMModel>();
                    MapUploadedDocRWQCTMModel MapObj;
                    if (model.AllUnCheckIds != null)
                    {
                        if (model.AllDocIds == null)
                        {
                            model.AllDocIds = "0";
                        }
                        long[] ids = model.AllDocIds.Split(',').Select(str => Int64.Parse(str)).ToArray();
                        long[] unids = model.AllUnCheckIds.Split(',').Select(str => Int64.Parse(str)).ToArray();
                        foreach (var item in unids)
                        {
                            MapObj = new MapUploadedDocRWQCTMModel();
                            string txtRSeq = "txtRkSeq_" + item;
                            string ddlType = "ddl_" + item;
                            string chk = "chkVDId_" + item;
                            string doctype = "doctype_" + item;
                            string strdocType = form[doctype];
                            MapObj.DocType = strdocType;

                            string docFrom = "docFrom_" + item;
                            string strdocFrom = form[docFrom];
                            MapObj.DocFrom = strdocFrom;

                            string docPath = "docPath_" + item;
                            string strdocPath = form[docPath];
                            MapObj.DocPath = strdocPath;

                            string docName = "docName_" + item;
                            string strdocName = form[docName];
                            MapObj.DocName = strdocName;
                            if (strdocType == "Check wise Document by API")
                            {
                                var res = new API().savedocumentinprovided(strdocName);
                            }
                            else if (strdocType == "Insuff Document by API")
                            {
                                var res = new API().savedocumentinprovided(strdocName);
                            }
                            byte RSeq = Convert.ToByte(form[txtRSeq]);
                            MapObj.RptArtiFacts = 0;
                            if (ids.Contains(item))
                            {
                                MapObj.RptArtiFacts = 1;
                            }
                            MapObj.VerifiedUploadRowID = item;
                            MapObj.RptArtiFactOrder = Convert.ToByte(form[txtRSeq]);
                            //if (model.ClientRowId == 268)
                            //{
                            if (form.AllKeys.Contains(ddlType))
                            {
                                MapObj.NewDocType = (form[ddlType].ToString());
                                GetTCSDocDetail(model.SubCheckRowID);
                            }
                            //}

                            MapObj.ClientRowId = model.ClientRowId;
                            dMapObj.Add(MapObj);
                        }
                    }
                    repoPQVerifiedUploadDoc.UpdateArtifactDocumentByRWQCTM(dMapObj, model.PersonalRowID, model.SubCheckRowID);

                    ViewBag.SuccessMsg = "Artifacts Mapped Successfully";
                    //return RedirectToAction("ManageCandidateChecksForReportQCTM", new { PersonalRowID = model.PersonalRowID, dispFor = "TeamMember" });
                }
                else
                {
                    var query = from state in ModelState.Values
                                from error in state.Errors
                                select error.ErrorMessage;

                    var errorList = query.ToList();
                    string strError = string.Empty;
                    foreach (string str in errorList)
                    {
                        strError += str + "\n";
                    }
                    ModelState.AddModelError("", strError);
                }
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            var CandDetail = repoPQPersonal.GetCandidateNameOrCmpIDById(model.PersonalRowID);
            model = repoPQVerifiedUploadDoc.GetCandidateUploadedDocListForRWQCTM(model.PersonalRowID, model.SubCheckRowID);

            model.ClientRowId = CandDetail.ClientRowID;
            GetTCSDocDetail(model.SubCheckRowID);
            return View(model);
        }

