        [NonAction]
        public bool ReadPDF(string pdfFileName, string fileP, string dbRefno, int clientRowId)
        {
            bool retVal = false;
            StringBuilder text = new StringBuilder();

            try
            {
                PdfReader pdfReader = new PdfReader(fileP);
                ITextExtractionStrategy strategy = new SimpleTextExtractionStrategy();
                string currentText = "";
                //if (dbRefno.Contains("NERPL")) 
                DataTable DT = new DataTable();
                cc = new ClientCustomize();


                //DT = cc.ONECheckNyakaaValidation(pdfFileName);
                //string CheckCount = DT.Rows[0]["checkNo"].ToString();

                //if ((clientRowId == 658 || clientRowId == 659 || clientRowId == 656 || clientRowId == 660 || clientRowId == 657) && CheckCount == "1")

                //    if ((clientRowId == 658 || clientRowId == 659 || clientRowId == 656 || clientRowId == 660 || clientRowId == 657) )
                //{
                //    currentText = PdfTextExtractor.GetTextFromPage(pdfReader, 2, strategy);
                //}
                //else
                //{
                currentText = PdfTextExtractor.GetTextFromPage(pdfReader, 1, strategy);
                // }
                currentText = Encoding.UTF8.GetString(ASCIIEncoding.Convert(Encoding.Default, Encoding.UTF8, Encoding.Default.GetBytes(currentText)));
                pdfReader.Close();
                if (pdfFileName.Contains("TechM"))
                {
                    dbRefno = dbRefno.Replace("TechM", "");
                }


                if (pdfFileName.Contains("IPSoft"))
                {
                    pdfFileName = pdfFileName.Replace("IPSoft", "");
                    dbRefno = dbRefno.Replace("IPSoft", "");
                }
                if (currentText.Contains(dbRefno))
                    retVal = true;
            }
            catch
            {
                if (pdfFileName == dbRefno)
                    retVal = true;
                else
                    retVal = false;

                if (dbRefno.Contains("TCS"))
                    retVal = true;


            }
            return retVal;
        }

