                    model.CriminalProvidedList = CRIProvidedList;

                }

                #endregion
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            Session["Type"] = "";
            return View(model);
        }

        [SessionExpireFilterAttribute]
        public ActionResult RWTMUserBucket(int page = 1, string sort = "", string sortDir = "asc", string Search = "", string CaseStatus = "", string version = "New", short ClientRowID = 0, short AllocateTM = 0, string PersonalIds = "", byte tatHours = 0)
        {
