        private string ReportArtifactsModeOfVerificationValidation(int personalRowId, InterimReportGenerateViewModel model)
        {
            string msg = "";
            DataTable dt = new DataTable();
            dt = cc.GetReportCheckStatus(personalRowId);
            if (dt.Rows.Count > 0)
            {
                for (int i = 0; i < dt.Rows.Count; i++)
                {
                    // pqc.PersonalRowID,pqc.SubCheckFamilyID,mcf.CheckFamilyRowID,mcf.CheckFamilyName
                    int Pid = Convert.ToInt32(dt.Rows[i]["PersonalRowID"].ToString());
                    int Sid = Convert.ToInt32(dt.Rows[i]["SubCheckFamilyID"].ToString());
                    string CheckFamilyName = dt.Rows[i]["CheckFamilyName"].ToString();
                    string SubCheckName = dt.Rows[i]["SubCheckName"].ToString();
                    int checkStatusId = Convert.ToInt32(dt.Rows[i]["CheckStatusID"].ToString());
                    if (checkStatusId == 36 || checkStatusId == 37)
                    {
                        DataTable dtapprove = cc.GetCheckReportArftApprove(Pid, Sid, CheckFamilyName);
                        string status = dtapprove.Rows[0]["docStatus"].ToString();
                        if (status == "Pending")
                        {
                            msg = "please approve artifacts " + SubCheckName + " with Ref No.  " + model.CompanyRefNo + "";
                            break;
                        }
                    }



                }
            }
            return msg;


        }

