        [HttpPost]
        public ActionResult GenerateWordFromHtml(string htmlContent)
        {
            try
            {
                // Step 1: Convert HTML to PDF using IronPDF
                var renderer = new IronPdf.ChromePdfRenderer();
                var pdfDocument = renderer.RenderHtmlAsPdf(htmlContent);
                byte[] pdfBytes = pdfDocument.BinaryData;

                if (pdfBytes == null || pdfBytes.Length == 0)
                {
                    return new HttpStatusCodeResult(HttpStatusCode.InternalServerError, "Failed to convert HTML to PDF");
                }


                // Then convert PDF to Word using PdfFocus
                var pdfFocus = new SautinSoft.PdfFocus();
                pdfFocus.OpenPdf(pdfBytes);

                using (var ms = new MemoryStream())
                {
                    int result = pdfFocus.ToWord(ms);
                    if (result != 0)
                    {
                        return new HttpStatusCodeResult(HttpStatusCode.InternalServerError, "Failed to convert PDF to Word");
                    }

                    return File(ms.ToArray(),
                              "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                              $"Report_{DateTime.Now:yyyyMMdd}.docx");
                }
            }
            catch (Exception ex)
            {
                return new HttpStatusCodeResult(HttpStatusCode.InternalServerError, ex.Message);
            }
        }

