        [HttpGet]
        public async Task<ActionResult> ReportConversion()
        {
            return View();
        }


        [HttpPost]
        public async Task<ActionResult> ReportConversion(HttpPostedFileBase pdfFile)
        {
            using (var client = new HttpClient())
            {
                // Localhost URL
                //string localApiUrl = "http://127.0.0.1:8080/converttoword";
                string localApiUrl = ConfigurationManager.AppSettings["WordDocumentUrl"].ToString();
                //string localApiUrl = "https://JatinChandani.pythonanywhere.com/converttoword";
                client.Timeout = TimeSpan.FromMinutes(5);
                string fname = System.IO.Path.GetFileNameWithoutExtension(pdfFile.FileName);
                string ext = System.IO.Path.GetExtension(pdfFile.FileName);
                string uniqueId = Guid.NewGuid().ToString();
                using (var content = new MultipartFormDataContent())
                {
                    var fileContent = new StreamContent(pdfFile.InputStream);
                    content.Add(fileContent, "file", fname + "_" + uniqueId + ext);

                    var response = await client.PostAsync(localApiUrl, content);

                    if (response.IsSuccessStatusCode)
                    {
                        var fileBytes = await response.Content.ReadAsByteArrayAsync();
                        Response.AppendCookie(new HttpCookie("fileDownloadToken", "true") { HttpOnly = false });
                        return File(fileBytes, "application/vnd.openxmlformats-officedocument.wordprocessingml.document", fname + ".docx");
                    }
                    else
                    {
                        return View();
                    }
                }
            }
        }

        [HttpPost]
        public async Task<ActionResult> ReportConversion1(Stream pdfStream, string fileName)
        {
            using (var client = new HttpClient())
            {
                string localApiUrl = ConfigurationManager.AppSettings["WordDocumentUrl"].ToString();

                client.Timeout = TimeSpan.FromMinutes(5);

                string fname = System.IO.Path.GetFileNameWithoutExtension(fileName);
                string ext = System.IO.Path.GetExtension(fileName);

                string uniqueId = Guid.NewGuid().ToString();

                using (var content = new MultipartFormDataContent())
                {
                    pdfStream.Position = 0;

                    var fileContent = new StreamContent(pdfStream);

                    content.Add(fileContent, "file", fname + "_" + uniqueId + ext);

                    var response = await client.PostAsync(localApiUrl, content);

                    if (response.IsSuccessStatusCode)
                    {
                        var fileBytes = await response.Content.ReadAsByteArrayAsync();

                        Response.AppendCookie(
                            new HttpCookie("fileDownloadToken", "true")
                            {
                                HttpOnly = false
                            });

                        return File(
                            fileBytes,
                            "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                            fname + ".docx");
                    }
                    else
                    {
                        return View();
                    }
                }
            }
        }
