        void SplitePDF(string filepath, int caseid)
        {
            iTextSharp.text.pdf.PdfReader reader = null;
            int currentPage = 1;
            int pageCount = 0;
            //string filepath_New = filepath + "\\PDFDestination\\";

            System.Text.UTF8Encoding encoding = new System.Text.UTF8Encoding();
            //byte[] arrayofPassword = encoding.GetBytes(ExistingFilePassword);
            reader = new iTextSharp.text.pdf.PdfReader(filepath);
            reader.RemoveUnusedObjects();
            pageCount = reader.NumberOfPages;
            string ext = System.IO.Path.GetExtension(filepath);
            for (int i = 1; i <= pageCount; i++)
            {
                iTextSharp.text.pdf.PdfReader reader1 = new iTextSharp.text.pdf.PdfReader(filepath);
                string outfile = filepath.Replace((System.IO.Path.GetFileName(filepath)), (System.IO.Path.GetFileName(filepath).Replace(".pdf", "") + "_" + i.ToString()) + ext);
                string outDir = System.IO.Path.GetDirectoryName(filepath);
                outDir = outDir + "\\" + caseid.ToString();
                try
                {
                    Directory.CreateDirectory(outDir);
                }
                catch { }
                outfile = outDir + "\\" + System.IO.Path.GetFileName(filepath).Replace(".pdf", "") + "_" + i.ToString() + ext;
                reader1.RemoveUnusedObjects();
                Document doc = new Document(reader.GetPageSizeWithRotation(currentPage));
                iTextSharp.text.pdf.PdfCopy pdfCpy = new iTextSharp.text.pdf.PdfCopy(doc, new System.IO.FileStream(outfile, System.IO.FileMode.Create));
                doc.Open();
                for (int j = 1; j <= 1; j++)
                {
                    iTextSharp.text.pdf.PdfImportedPage page = pdfCpy.GetImportedPage(reader1, currentPage);
                    //pdfCpy.SetFullCompression();
                    pdfCpy.AddPage(page);
                    currentPage += 1;
                }
                doc.Close();
                pdfCpy.Close();
                reader1.Close();
                reader.Close();

            }
        }

        public void CandidatePdfListsCompress(int id, int dpi)
        {
            string DocPath1 = ConfigurationManager.AppSettings["provideddocumentsCompress"].ToString();
            string DocPath = ConfigurationManager.AppSettings["provideddocuments"].ToString();
            var CandidatePdfList = repoReportQC.GetCandidatePdfListForConversion(id);
            foreach (var item in CandidatePdfList)
            {
                SautinSoft.PdfFocus f = new SautinSoft.PdfFocus();
                f.Serial = "80027423579"; //License for server 
                //f.Serial = "10273316474"; //License for development machine
                f.OpenPdf(Server.MapPath(DocPath + item.DocFile));

                if (f.PageCount > 0)
                {
                    string jpgFileName = item.DocFile.Replace(".pdf", "");
                    string ImageName = string.Empty;
                    for (int i = 1; i <= f.PageCount; i++)
                    {
                        ImageName += jpgFileName + i + ".jpg,";
                    }
                    if (!string.IsNullOrEmpty(ImageName) && ImageName.Length > 0)
                    {
                        ImageName = ImageName.Substring(0, ImageName.Length - 1);
                        bool res = repoReportQC.UpdateImageName(item.VerifiedUploadRowID, ImageName);
                        if (res)
                        {
                            //int width = 644; // Width in Px
