                        }
                        //cc.updateReportPDFToImagePages(item.VerifiedUploadRowID, ImageName);
                    }
                }
                f.ClosePdf();

               
                if (pdfToProcess != originalPdfPath && System.IO.File.Exists(pdfToProcess))
                {
                    System.IO.File.Delete(pdfToProcess);
                }
            }
        }

        private string FlattenHighlightAnnotations(string pdfPath)
        {
            try
            {
                string tempPdf = System.IO.Path.Combine(System.IO.Path.GetDirectoryName(pdfPath), "temp_" + System.IO.Path.GetFileName(pdfPath));
                bool hasHighlight = false;

                using (iTextSharp.text.pdf.PdfReader reader = new iTextSharp.text.pdf.PdfReader(pdfPath))
                {
                    using (System.IO.FileStream fs = new System.IO.FileStream(tempPdf, System.IO.FileMode.Create, System.IO.FileAccess.Write))
                    {
                        using (iTextSharp.text.pdf.PdfStamper stamper = new iTextSharp.text.pdf.PdfStamper(reader, fs))
                        {
                            for (int pageNum = 1; pageNum <= reader.NumberOfPages; pageNum++)
                            {
                                iTextSharp.text.pdf.PdfDictionary pageDict = reader.GetPageN(pageNum);
                                iTextSharp.text.pdf.PdfArray annots = pageDict.GetAsArray(iTextSharp.text.pdf.PdfName.ANNOTS);

                                if (annots != null && annots.Size > 0)
                                {
                                    iTextSharp.text.pdf.PdfContentByte canvas = stamper.GetUnderContent(pageNum);

                                    for (int i = annots.Size - 1; i >= 0; i--)
                                    {
                                        iTextSharp.text.pdf.PdfDictionary annot = annots.GetAsDict(i);
                                        if (annot != null && iTextSharp.text.pdf.PdfName.HIGHLIGHT.Equals(annot.GetAsName(iTextSharp.text.pdf.PdfName.SUBTYPE)))
                                        {
                                            iTextSharp.text.pdf.PdfArray rect = annot.GetAsArray(iTextSharp.text.pdf.PdfName.RECT);
                                            if (rect != null && rect.Size == 4)
                                            {
                                                float x1 = rect.GetAsNumber(0).FloatValue;
                                                float y1 = rect.GetAsNumber(1).FloatValue;
                                                float x2 = rect.GetAsNumber(2).FloatValue;
                                                float y2 = rect.GetAsNumber(3).FloatValue;

                                                canvas.SaveState();
                                                canvas.SetColorFill(iTextSharp.text.BaseColor.YELLOW);
                                                canvas.Rectangle(x1, y1, x2 - x1, y2 - y1);
                                                canvas.Fill();
                                                canvas.RestoreState();

                                                annots.Remove(i);
                                                hasHighlight = true;
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }

                if (hasHighlight && System.IO.File.Exists(tempPdf))
                {
                    return tempPdf;
                }
                else if (System.IO.File.Exists(tempPdf))
                {
                    System.IO.File.Delete(tempPdf);
                }
            }
            catch
            {
               
            }
            return pdfPath;
        }



