        [HttpPost]
        public ActionResult ApproveRejectRWTMQC(int id, string Actions, string CaseStatus, string Remarks)
        {
            short teamMemberId = Convert.ToInt16(Session["TeamMemberRowID"]);
            if (Actions == "Approve")
            {
                ClientCustomize cc = new ClientCustomize();

                DataTable dt = new DataTable();
                dt = cc.GetReportUploadDetails(id);
                if (dt.Rows.Count > 0)
                {
                    string SecuId = dt.Rows[0]["Companyrefno"].ToString();
                    string rep_status = dt.Rows[0]["rep_status"].ToString();
                    string ColorName = dt.Rows[0]["ColorName"].ToString();

                    if (rep_status == "Interim" || rep_status == "YTR Report")
                    {
                        cc.UpdateRWTMQCUser(id, teamMemberId);
                        cc.Process_Remarks_Insert(id, 0, 106, Remarks, "RWQC-QCLevel Interim Approved", teamMemberId);
                        #region Case Action history save
                        //clsCommonMethods.AddCaseActionHistory(id, "Completed", "Completed");
                        clsCommonMethods.AddCaseActionHistory(id, "QcPendingApproved", "QcPendingApproved");
                        #endregion
                        cc.updateTCSDBReport(id, "QcPendingApproved");
                    }
                    if (rep_status == "Final" || rep_status == "SR Report")
                    {
                        cc.InsertColorCodeReview(id, 106, ColorName, rep_status, teamMemberId, 0, "");
                        //  cc.UpdateCaseStatus(id, 30, teamMemberId);
                        cc.UpdateRWTMQCUser(id, teamMemberId);
                        #region Case Action history save
                        //clsCommonMethods.AddCaseActionHistory(id, "Completed", "Completed");
                        clsCommonMethods.AddCaseActionHistory(id, "Color Code Review", "Color Code Review");
                        #endregion
                        // SendAlertMassageForReportSubmit(SecuId, rep_status, ColorName, null, "Report", 0, 1);
                        //cc.Process_Remarks_Insert(id, 0, 30, Remarks, "RWQC-QCLevel", teamMemberId);
                        cc.Process_Remarks_Insert(id, 0, 106, Remarks, "RWQC-QCLevel", teamMemberId);
                    }


                }

            }
            else if (Actions == "Reject")
            {
                ClientCustomize cc = new ClientCustomize();
                DataTable dt = new DataTable();
                dt = cc.GetReportUploadDetails(id);
                if (dt.Rows.Count > 0)
                {
                    string SecuId = dt.Rows[0]["Companyrefno"].ToString();
                    string rep_status = dt.Rows[0]["rep_status"].ToString();
                    string ColorName = dt.Rows[0]["ColorName"].ToString();


                    if (rep_status == "Interim")
                    {
                        cc.UpdateRWTMQCUser(id, teamMemberId);
                        cc.Process_Remarks_Insert(id, 0, 115, Remarks, "RWQC-QCLevel Interim Reject", teamMemberId);
                        #region Case Action history save
                        clsCommonMethods.AddCaseActionHistory(id, "QcPendingRejected", "QcPendingRejected");
                        #endregion
                        cc.updateTCSDBReport(id, "QcPendingRejected");
                    }
                    if (rep_status == "Final")
                    {
                        cc.UpdateCaseStatus(id, 115, teamMemberId);
                        cc.UpdateRWTMQCUser(id, teamMemberId);
                        #region Case Action history save
                        clsCommonMethods.AddCaseActionHistory(id, "QC Rejected", "QC Rejected");
                        #endregion
                        cc.Process_Remarks_Insert(id, 0, 115, Remarks, "RWQC-QCLevel", teamMemberId);
                    }
                }


            }
            return RedirectToAction("GetRWQCTeamMemberDashBoardInfo", "ReportQC", new { CaseStatus = CaseStatus, version = "New" });
        }

