        [HttpPost]
        [ValidateInput(false)]
        [SessionExpireFilterAttribute]
        public ActionResult ConverdReportPDFFileToWord(InterimReportGenerateViewModel model, HttpPostedFileBase file, string ReportToPDF, string userhtml, string Refno, string ClientRowID = "")
        {
            try
            {
                string IronKey = System.Configuration.ConfigurationManager.AppSettings["IronKey"].ToString();
                var Renderer = new IronPdf.ChromePdfRenderer();
                IronPdf.License.LicenseKey = IronKey;
                //IronPdf.License.LicenseKey = "IRONPDF-MYLICENSE-KEY-1EF01";
                Renderer.RenderingOptions.PaperSize = IronPdf.Rendering.PdfPaperSize.Custom;
                if (ClientRowID == "1218")
                {
                    Renderer.RenderingOptions.SetCustomPaperSizeinPixelsOrPoints(700, 1050);
                }
                else
                {
                    Renderer.RenderingOptions.PaperSize = IronPdf.Rendering.PdfPaperSize.Custom;
                }
                Renderer.RenderingOptions.MarginTop = 3;
                Renderer.RenderingOptions.MarginLeft = 5;
                Renderer.RenderingOptions.MarginRight = 5;
                Renderer.RenderingOptions.MarginBottom = 3;
                var PDF = Renderer.RenderHtmlAsPdf(userhtml);

                model.CompanyRefNo = Refno;
                if (model.ClientRowID == 762)
                {
                    int userId = Convert.ToInt32(Session["TeamMemberRowID"].ToString());
                    string FldPathDoc = string.Empty;
                    FldPathDoc = ConfigurationManager.AppSettings["CandidateReportdoc".Trim().ToLower()].ToString();
                    string ImgName = model.CompanyRefNo + ".pdf";
                    string fileSavePath = Server.MapPath(FldPathDoc + ImgName);
                    PDF.SaveAs(fileSavePath);
                    ClientCustomize cc = new ClientCustomize();
