        [HttpPost]
        [ValidateInput(false)]
        [SessionExpireFilterAttribute]
        public async Task<ActionResult> ConverdReportPDFFileToWordTCSNew(InterimReportGenerateViewModel model, HttpPostedFileBase file, string ReportToPDF, string userhtml, string Refno, string ClientRowID = "")
        {
            try
            {
                string IronKey = System.Configuration.ConfigurationManager.AppSettings["IronKey"].ToString();
                var Renderer = new IronPdf.ChromePdfRenderer();
                IronPdf.License.LicenseKey = IronKey;

                // 1. Browser print engine ki tarah behave karne ke liye screen/print trigger on karein
                // DoPDF engine layout match karne ke liye Screen media select karein (Print ki jagah)
                Renderer.RenderingOptions.CssMediaType = IronPdf.Rendering.PdfCssMediaType.Screen;
                Renderer.RenderingOptions.PaperSize = IronPdf.Rendering.PdfPaperSize.A4;

                Renderer.RenderingOptions.PrintHtmlBackgrounds = true;
                // Margins ko browser print layout ki tarah standard (0.5 inch) rakhein
                Renderer.RenderingOptions.MarginTop = 10;
                Renderer.RenderingOptions.MarginLeft = 10;
                Renderer.RenderingOptions.MarginRight = 10;
                Renderer.RenderingOptions.MarginBottom = 10;

                // 2. CSS aur images load hone ke liye 2 second ka delay dein (Taaki layout na bigde)
                Renderer.RenderingOptions.RenderDelay = 2000;

                // 3. Server par rakhi 'report.css' ka sahi absolute path nikalne ke liye base URL banayein
                string baseUrl = string.Format("{0}://{1}", Request.Url.Scheme, Request.Url.Authority);

                // HTML string ke andar agar css link relative hai toh use full path me badlein
                if (userhtml.Contains("/Images/report.css") && !userhtml.Contains(baseUrl))
                {
                    userhtml = userhtml.Replace("/Images/report.css", baseUrl + "/Images/report.css");
                }
                else if (!userhtml.Contains("report.css"))
                {
                    // Agar HTML me head tag me css nahi hai, toh use forcibly upar insert kar dein
                    string cssLink = $"<link href='{baseUrl}/Images/report.css' rel='stylesheet' type='text/css' />";
                    userhtml = userhtml.Insert(userhtml.IndexOf("<body>"), cssLink);
                }

                // 4. Base URL ke sath render karein taaki sari external files backend engine fetch kar sake
                var PDF = Renderer.RenderHtmlAsPdf(userhtml, baseUrl);

                model.CompanyRefNo = Refno;
                return await ReportConversion1(PDF.Stream, model.CompanyRefNo + ".pdf");
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            return View();
        }


