        #region ****** PDF Compress New Code SA ******

        private void OptimizeJpeg(string filePath, long quality)
        {
            string tempFile = filePath + ".tmp";

            using (System.Drawing.Image image =
                   System.Drawing.Image.FromFile(filePath))
            {
                System.Drawing.Imaging.ImageCodecInfo jpegCodec =
                    System.Drawing.Imaging.ImageCodecInfo.GetImageEncoders()
                        .First(c =>
                            c.FormatID == System.Drawing.Imaging.ImageFormat.Jpeg.Guid);

                using (System.Drawing.Imaging.EncoderParameters encoderParameters =
                       new System.Drawing.Imaging.EncoderParameters(1))
                {
                    encoderParameters.Param[0] =
                        new System.Drawing.Imaging.EncoderParameter(
                            System.Drawing.Imaging.Encoder.Quality,
                            quality);

                    image.Save(
                        tempFile,
                        jpegCodec,
                        encoderParameters);
                }
            }

            System.IO.File.Delete(filePath);
            System.IO.File.Move(tempFile, filePath);
        }

        public void CandidatePdfListsLTI_NewSA(int id, int dpi)
        {
            string DocPath = ConfigurationManager.AppSettings["provideddocuments"].ToString();
            string DocPath1 = ConfigurationManager.AppSettings["provideddocuments"].ToString();
            var CandidatePdfList = repoReportQC.GetCandidatePdfListForConversion_Address(id);
            foreach (var item in CandidatePdfList)
            {
                var pdf = new IronPdf.PdfDocument(Server.MapPath(DocPath + item.DocFile));

                if (pdf.PageCount > 0)
                {
                    string jpgFileName = item.DocFile.Replace(".pdf", "");


                    string ImageName = string.Empty;
                    for (int i = 1; i <= pdf.PageCount; i++)
                    {
                        ImageName += jpgFileName + "_" + i + ".jpg,";
                    }
                    if (!string.IsNullOrEmpty(ImageName) && ImageName.Length > 0)
                    {
                        ImageName = ImageName.Substring(0, ImageName.Length - 1);
                        bool res = repoReportQC.UpdateImageName(item.VerifiedUploadRowID, ImageName);
                        if (res)
                        {
                            pdf.RasterizeToImageFiles(Server.MapPath(@DocPath) + jpgFileName + "_" + "*.jpg");

                            for (int page = 1; page <= pdf.PageCount; page++)
                            {
                                string jpgPath = System.IO.Path.Combine(
                                    Server.MapPath(DocPath),
                                    jpgFileName + "_" + page + ".jpg"
                                );

                                if (System.IO.File.Exists(jpgPath))
                                {
                                    OptimizeJpeg(jpgPath, 90L);
                                }
                            }
                        }
                    }
                }
            }
        }

        public void CandidatePdfLists_NewSA(int id, int dpi)
        {
            string DocPath = ConfigurationManager.AppSettings["provideddocuments"].ToString();
            var CandidatePdfList = repoReportQC.GetCandidatePdfListForConversion(id);
            foreach (var item in CandidatePdfList)
            {
                SautinSoft.PdfFocus f = new SautinSoft.PdfFocus();
                f.Serial = "80027423579"; //License for server 
                //f.Serial = "10273316474"; //License for development machine
                f.OpenPdf(Server.MapPath(DocPath + item.DocFile));

                if (f.PageCount > 0)
                {
                    string jpgFileName = item.DocFile.Replace(".pdf", "");
                    string ImageName = string.Empty;
                    for (int i = 1; i <= f.PageCount; i++)
                    {
                        ImageName += jpgFileName + i + ".jpg,";
                    }
                    if (!string.IsNullOrEmpty(ImageName) && ImageName.Length > 0)
                    {
                        ImageName = ImageName.Substring(0, ImageName.Length - 1);
                        bool res = repoReportQC.UpdateImageName(item.VerifiedUploadRowID, ImageName);
                        if (res)
                        {
                            //int width = 644; // Width in Px
                            //int height = 911; // Height in Px
                            f.ImageOptions.ImageFormat = System.Drawing.Imaging.ImageFormat.Jpeg;
                            //f.ImageOptions.Resize(new System.Drawing.Size { Width = width, Height = height }, false);
                            f.ImageOptions.Dpi = dpi;
                            f.ToImage(Server.MapPath(DocPath), jpgFileName);

                            // optimize Generated JPG files 
                            for (int page = 1; page <= f.PageCount; page++)
                            {
                                string jpgPath = System.IO.Path.Combine(
                                    Server.MapPath(DocPath),
                                    jpgFileName + page + ".jpg"
                                );

                                if (System.IO.File.Exists(jpgPath))
                                {
                                    OptimizeJpeg(jpgPath, 90L);
                                }
                            }

                        }
                    }
                }
            }
        }

