        public void ExportToExcel(DataTable dt, string strFileName)
        {
            if (dt.Rows.Count > 0)
            {
                Response.Clear();
                System.IO.StringWriter tw = new System.IO.StringWriter();
                System.Web.UI.HtmlTextWriter hw = new System.Web.UI.HtmlTextWriter(tw);
                DataGrid dgGrid = new DataGrid();
                dgGrid.DataSource = dt;
                dgGrid.DataBind();
                dgGrid.GridLines = GridLines.None;
                dgGrid.BorderStyle = BorderStyle.None;
                //Get the HTML for the control.
                dgGrid.RenderControl(hw);
                //Write the HTML back to the browser.
                //Response.ContentType = application/vnd.ms-excel;
                Response.ContentType = "application/vnd.ms-excel";
                Response.AppendHeader("Content-Disposition", "attachment; filename=" + strFileName + ".xls");
                Response.ContentEncoding = System.Text.Encoding.UTF8;
                Response.BinaryWrite(System.Text.Encoding.UTF8.GetPreamble());
                Response.Write(tw.ToString());
                Response.End();
            }
        }
        public async Task<ActionResult> GetDigitalLOAByPersonalRowID(int PersonalRowID)
        {
            ClientCustomize cc = new ClientCustomize();
            DataTable dt = cc.GetLatestDigitalLOAByPersonalRowID(PersonalRowID);

            if (dt.Rows.Count == 0)
            {
                return Content("No LOA found for this candidate.");
            }

            string fileName = dt.Rows[0]["FileName"].ToString();
            string filePath = dt.Rows[0]["FilePath"].ToString();

            if (filePath.StartsWith("~/"))
            {
                filePath = filePath.Replace("~/", @"D:/wwwroot2/");
            }
            if (filePath.StartsWith("/"))
            {
                filePath = @"D:/wwwroot2/" + filePath.Substring(1);
            }

            HttpResponseMessage response = await _documentService.GetDocumentAsync(fileName, filePath);
            if (response.IsSuccessStatusCode)
            {
                var jsonString = await response.Content.ReadAsStringAsync();
                var obj = JsonConvert.DeserializeObject<DocumentResponse>(jsonString);

                byte[] fileBytes = Convert.FromBase64String(obj.DocumentValue);
                string contentType = System.Web.MimeMapping.GetMimeMapping(fileName);
                return File(fileBytes, contentType, fileName);
            }

            return Content("Unable to retrieve LOA document.");
        }

        #region ********** Export To Excel **********

        public void ExportToExcel<T>(IEnumerable<T> list, string strFileName)
        {
            // Step 1 - get the data from database
            var data = list.ToList();

            // instantiate the GridView control from System.Web.UI.WebControls namespace
            // set the data source
            GridView gridview = new GridView();
            gridview.DataSource = data;
            gridview.DataBind();

            // Clear all the content from the current response
            Response.ClearContent();
            Response.Buffer = true;

            // set the header
            Response.AddHeader("content-disposition", "attachment;filename=" + strFileName + ".xls");
            Response.AddHeader("Content-Type", "application/vnd.ms-excel");
            clsExportDataToExcel.WriteHtmlTable(data, Response.Output);

            Response.Flush();
            Response.End();
        }

        #endregion

