        {
            PQPersonalReportQCListPagedModel model = new PQPersonalReportQCListPagedModel();
            short teamMemberId = Convert.ToInt16(Session["TeamMemberRowID"]);
            try
            {
                if (AllocateTL > 0 && !string.IsNullOrEmpty(PersonalIds))
                {
                    byte UnAllocatedCount = 0;
                    int[] PerIDs = PersonalIds.Split(',').Select(x => int.Parse(x)).ToArray();
                    string[] candTitles = CandTitle.Split(',');
                    if (PerIDs.Length != candTitles.Length)
                    {
                        throw new Exception("PersonalIds and CandTitle count mismatch");
                    }
                    ReportQCAllocationViewModel personalmodel = new ReportQCAllocationViewModel();
                    personalmodel.ModifiedBy = teamMemberId;
                    personalmodel.ModifiedDate = DateTime.Now;
                    personalmodel.CheckStatus = "Allocated-TL";
                    personalmodel.RWQCTeamMemberBy = AllocateTL;
                    personalmodel.RWQCTeamMemberDate = DateTime.Now;
                    for (int i = 0; i < PerIDs.Length; i++)
                    {
                        int personalRowId = PerIDs[i];
                        string candTitleForThatRow = candTitles[i];
                        personalmodel.PersonalRowID = personalRowId;

                        short ClientID = repoPQPersonal.GetClientDetailsByPersonalId(personalRowId);
                        bool result = repoPQClientTMember.IsClientDepartTeamMembersExist(ClientID, personalmodel.RWQCTeamMemberBy, "Quality Check", "Team Leader Quality Check");
                        ClientCustomize cc = new ClientCustomize();
                        if (result)
                        {
                            //repoReportQC.UpdateAllocationForRWQCTLByRWQCManager(personalmodel);

                            cc.UpdateAllocationForRWQCTLByRWQCManager(personalmodel.PersonalRowID, personalmodel.CheckStatus, personalmodel.RWQCTeamMemberBy);


                            if (candTitleForThatRow == "BGV2")
                            {
                                cc.UpdateReportStatusTCSDB(personalmodel.PersonalRowID, AllocateTL, "BGV2", "AllocateTOTL");
                            }

                            if (candTitleForThatRow == "TCSAutoUnallocated")
                            {
                                cc.UpdateReportStatusTCSDB(personalmodel.PersonalRowID, AllocateTL, "TCSInterim", "AllocateTOTL");
