        [ValidateInput(false)]
        public ActionResult CompressSize(HttpPostedFileBase file, FormCollection form)
        {
            try
            {
                // Validate file input
                if (file == null || file.ContentLength == 0 || System.IO.Path.GetExtension(file.FileName).ToLower() != ".pdf")
                {
                    TempData["ErrorMsg"] = "Please upload a valid .pdf file.";
                    return View();
                }

                // Parse inputs
                if (!int.TryParse(form["PdfSize"], out int pdfSize))
                {
                    TempData["ErrorMsg"] = "Invalid PDF compression size.";
                    return View();
                }

                if (Session["TeamMemberRowID"] == null || !int.TryParse(Session["TeamMemberRowID"].ToString(), out int userId))
                {
                    TempData["ErrorMsg"] = "User session expired. Please login again.";
                    return View();
                }
                pdfSize = 100 - pdfSize;
                // Save original file
                string fileName = System.IO.Path.GetFileName(file.FileName);
                string uploadPath = Server.MapPath("~/CompressReportSize/");
                string filePath = System.IO.Path.Combine(uploadPath, fileName);
                Directory.CreateDirectory(uploadPath); // Ensure directory exists
                file.SaveAs(filePath);

                // Compress PDF using IronPDF
                var pdf = new IronPdf.PdfDocument(filePath);
                pdf.CompressImages(pdfSize, ScaleToVisibleSize: true);
                pdf.SaveAs(filePath);

                // Read compressed file
                byte[] data = System.IO.File.ReadAllBytes(filePath);

                // Password protect if necessary
                var model = new UpdateTempPQPersonalViewModel(); // You need to populate this from somewhere meaningful
                if (model.ClientRowID == 113)
                {
                    string password = "mlbg8"; // Consider moving this to secure config
                    using (var input = new MemoryStream(data))
                    using (var output = new MemoryStream())
                    {
                        PdfReader reader = new PdfReader(input);
                        PdfEncryptor.Encrypt(reader, output, true, password, password, PdfWriter.ALLOW_SCREENREADERS);
                        data = output.ToArray();
                    }

                    return File(data, "application/pdf", $"{model.PersonalRowID}");
                }
                else
                {
                    return File(data, "application/pdf", System.IO.Path.GetFileName(filePath));
                }
            }
            catch (Exception ex)
            {
                // Log the error
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), ex.Message, ex.StackTrace);
                ViewBag.ErrorMsg = "An error occurred while processing the file: " + ex.Message;
                return View();
            }
        }


