        [HttpPost]
        public JsonResult SplitMargePdf(string pfm, string pft)
        {
            List<PdfReader> readerList = new List<PdfReader>();
            int pageform = Convert.ToInt32(pfm);
            int pageto = Convert.ToInt32(pft);
            string strOutPath = Server.MapPath("~/Documents/SplitDocuments/") + Session["WebUserRowid"].ToString() + @"\Split";
            // ClearDirectory(strOutPath);
            if (!Directory.Exists(strOutPath))
            {
                Directory.CreateDirectory(strOutPath);
            }
            string strPath = Server.MapPath("~/Documents/Upload");
            string _FileName = GetUploadedFileName(strPath);
            string _path = System.IO.Path.Combine(strPath, _FileName);
            SplitAndSave(_path, strOutPath);

            string sfilePath = Server.MapPath("~/Documents/SplitDocuments/") + Session["WebUserRowid"].ToString() + @"\Split";
            for (int i = pageform; i <= pageto; i++)
            {
                string fileName = Session["GUID"].ToString() + i.ToString() + ".pdf";
                string strPathToRead = System.IO.Path.Combine(sfilePath, fileName);
                if (System.IO.File.Exists(strPathToRead))
                {
                    PdfReader pdfReader = new PdfReader(strPathToRead);
                    readerList.Add(pdfReader);
                }


            }
            Document document = new Document(PageSize.A4, 0, 0, 0, 0);
            string mfilePath = Server.MapPath("~/Documents/Merge/");
            if (!Directory.Exists(mfilePath))
            {
                Directory.CreateDirectory(mfilePath);
            }

            string fname = DateTime.Now.ToString("ddmmyyyhhss");
            PdfWriter writer = PdfWriter.GetInstance(document, new FileStream(mfilePath + fname + ".pdf", FileMode.Create));
            document.Open();
            foreach (PdfReader reader in readerList)
            {
                for (int i = 1; i <= reader.NumberOfPages; i++)
                {
                    PdfImportedPage page = writer.GetImportedPage(reader, i);
                    document.Add(iTextSharp.text.Image.GetInstance(page));
                }
            }
            document.Close();
            string result = fname + ".pdf";
            return Json(result, JsonRequestBehavior.AllowGet);
        }

        private string GetUploadedFileName(string strPath)
        {
            string fname = "";
            System.IO.DirectoryInfo df = new DirectoryInfo(strPath);
            FileInfo[] Files = df.GetFiles("*.pdf");
            if (Files.Length >= 1)
            {
                fname = Files[0].ToString();
            }

            return fname;
        }

        public FileResult DownloadFile(string fName)
        {
            string path = Server.MapPath("~/Documents/Merge/") + fName;
            byte[] bytes = System.IO.File.ReadAllBytes(path);
            //Send the File to Download.
            System.IO.File.Delete(path);
            return File(bytes, "application/octet-stream", fName);
            // return File(ms, "application/pdf", fName);
        }

        private void ClearDirectory(string filePath)
        {
            try
            {
                if (Directory.Exists(filePath))
                {
                    System.IO.DirectoryInfo di = new DirectoryInfo(filePath);
                    foreach (FileInfo file in di.GetFiles())
                    {
                        file.Delete();
                    }
                }
                else
                {
                    Directory.CreateDirectory(filePath);
                }
            }
            catch (Exception ex)
            {
                string str = ex.Message;
            }
        }
        public int SplitAndSave(string inputPath, string outputPath)
        {
            FileInfo file = new FileInfo(inputPath);
            string name = file.Name.Substring(0, file.Name.LastIndexOf("."));
            using (PdfReader reader = new PdfReader(inputPath))
            {
                for (int i = 1; i <= reader.NumberOfPages; i++)
                {
                    string fileName = Session["GUID"].ToString() + i.ToString() + ".pdf";
                    string outPath = outputPath + "\\" + fileName;
                    if (System.IO.File.Exists(outPath))
                    {
                        return i;
                    }
                    Document document = new Document();
                    PdfCopy copy = new PdfCopy(document, new FileStream(outPath, FileMode.Create));
                    document.Open();
                    copy.AddPage(copy.GetImportedPage(reader, i));
                    document.Close();
                }
                reader.Close();

                return reader.NumberOfPages;
            }

        }
