                        PdfReader pdfReader = new PdfReader(Docpath);
                        pdfReaderList.Add(pdfReader);
                    }
                }
                Response.ClearContent();
                Response.ClearHeaders();
                Response.Buffer = true;

                Document document = new Document(PageSize.A4, 0, 0, 0, 0);
                PdfWriter writer = PdfWriter.GetInstance(document, new FileStream(Server.MapPath("~/Documents/") + "Marge.pdf", FileMode.Create));
                document.Open();
                foreach (PdfReader reader in pdfReaderList)
                {
                    for (int i = 1; i <= reader.NumberOfPages; i++)
                    {
                        PdfImportedPage page = writer.GetImportedPage(reader, i);
                        document.Add(iTextSharp.text.Image.GetInstance(page));
                    }
                }
                document.Close();
                string pathD = Server.MapPath("~/Documents/Marge.pdf");
                System.Net.WebClient client = new System.Net.WebClient();
                Byte[] buffer = client.DownloadData(pathD);
                if (buffer != null)
                {
                    Response.Clear();
                    Response.ContentType = "application/pdf";
                    Response.AddHeader("content-disposition", "attachment;filename=" + "Marge.pdf");
                    Response.Cache.SetCacheability(HttpCacheability.NoCache);
                    Response.BinaryWrite(buffer);
                    Response.End();
                }
                DataTable dtd = new DataTable();
                dtm = cc.Deletemargepdf(Convert.ToInt32(UserID));
            }
            return RedirectToAction("MargePdfInterval");
        }

