        [SessionExpireFilterAttribute]
        public ActionResult GetAccentureDocumentReports(int PersonalRowID, int SubCheckRowID, int family)
        {
            ClientCustomize cc = new ClientCustomize();
            DataTable dt = cc.GetAccentureDocumentReports(family, PersonalRowID, SubCheckRowID);
            string imgname = dt.Rows[0]["filename"].ToString();
            //imgname = imgname.Replace(".pdf", "");
            string FldPathDoc = System.Configuration.ConfigurationManager.AppSettings["provideddocuments"].ToString();
            byte[] fileBytes = null;

            if (System.IO.File.Exists(Server.MapPath(FldPathDoc) + imgname))
            {
                fileBytes = System.IO.File.ReadAllBytes(Server.MapPath(FldPathDoc) + imgname);
            }
            if (System.IO.File.Exists(Server.MapPath(FldPathDoc) + imgname))
            {
                fileBytes = System.IO.File.ReadAllBytes(Server.MapPath(FldPathDoc) + imgname);
            }
            if (fileBytes != null)
                return File(fileBytes, MediaTypeNames.Application.Octet, imgname);
            else
            {
                return RedirectToAction("ManageCandidateChecksForReportQCTM", new { PersonalRowID = PersonalRowID, dispFor = "TeamMember" });
            }

        }


        [HttpGet]
        [SessionExpireFilterAttribute]
        [ValidateInput(false)]
        public ActionResult UpdateAllChecksDetails(int id, string CaseStatus = "", string version = "")
        {

            dynamic expando = new ExpandoObject();
            string SubCheckIds = "";
            string ClientRowID = "";
            var marksModel = expando as IDictionary<string, object>;
            ClientCustomize cc = new ClientCustomize();
            //ViewBag.PersonalBind = repoPQPersonal.GetPersonalDetailsForTM(PersonalRowID, subCheckId);
            DataTable Personaldt = new DataTable();
            Personaldt = cc.GetPersonalDetailsWithsubCheckId(id);
            if (Personaldt.Rows.Count > 0)
            {
                for (int i = 0; i < Personaldt.Rows.Count; i++)
                {
                    if (i == 0)
                    {
                        SubCheckIds = Personaldt.Rows[i]["SubCheckFamilyID"].ToString();
                        ClientRowID = Personaldt.Rows[i]["ClientRowID"].ToString();
                    }
                    else { SubCheckIds = SubCheckIds + "," + Personaldt.Rows[i]["SubCheckFamilyID"].ToString(); }
                }
            }
            DataTable dt = new DataTable();

            dt = cc.Antecedents_client_select_form_ALLNew(SubCheckIds, ClientRowID, id);
            DataTable dbValue = new DataTable();

            dbValue = cc.GetReportValue_Report(id, SubCheckIds);

            DataTable dts = cc.GetDispositionPQCandidateChecks_Report(id, SubCheckIds);
            string SeverityRowID = "";
            string ColorCode = "";
            string SeverityGrid = "";
            string ReportComment = "";
            if (dts.Rows.Count > 0)
            {
                for (int i = 0; i < dts.Rows.Count; i++)
                {
                    if (dts.Rows[i]["SubCheckFamilyID"].ToString() == "69")
                    {
                        var Status = dts.Rows[i]["Status"].ToString();
                        ViewBag.Status = Status;
                    }
                    else if (dts.Rows[i]["SubCheckFamilyID"].ToString() == "70")
                    {
                        var Status1 = dts.Rows[i]["Status"].ToString();
                        ViewBag.Status1 = Status1;
                    }
                    else if (dts.Rows[i]["SubCheckFamilyID"].ToString() == "71")
                    {
                        var Status2 = dts.Rows[i]["Status"].ToString();
                        ViewBag.Status2 = Status2;
                    }
                    else if (dts.Rows[i]["SubCheckFamilyID"].ToString() == "72")
                    {
                        var Status3 = dts.Rows[i]["Status"].ToString();
                        ViewBag.Status3 = Status3;
                    }
                    else if (dts.Rows[i]["SubCheckFamilyID"].ToString() == "73")
                    {
                        var Status4 = dts.Rows[i]["Status"].ToString();
                        ViewBag.Status4 = Status4;
                    }

                    if (i == 0)
                    {
                        SeverityRowID = dts.Rows[i]["SeverityRowID"].ToString() + "_" + dts.Rows[i]["SubCheckFamilyID"].ToString();
                        ColorCode = dts.Rows[i]["ColorName"].ToString() + "_" + dts.Rows[i]["SubCheckFamilyID"].ToString();
                        SeverityGrid = dts.Rows[i]["SeverityGrid"].ToString() + "_" + dts.Rows[i]["SubCheckFamilyID"].ToString();
                        ReportComment = dts.Rows[i]["ReportComments"].ToString().Trim() + "_" + dts.Rows[i]["SubCheckFamilyID"].ToString();
                    }
                    else
                    {
                        SeverityRowID += "|" + dts.Rows[i]["SeverityRowID"].ToString() + "_" + dts.Rows[i]["SubCheckFamilyID"].ToString();
                        ColorCode += "|" + dts.Rows[i]["ColorName"].ToString() + "_" + dts.Rows[i]["SubCheckFamilyID"].ToString();
                        SeverityGrid += "|" + dts.Rows[i]["SeverityGrid"].ToString() + "_" + dts.Rows[i]["SubCheckFamilyID"].ToString();
                        ReportComment += "|" + dts.Rows[i]["ReportComments"].ToString().Trim() + "_" + dts.Rows[i]["SubCheckFamilyID"].ToString();
                    }
                }

                ViewBag.SeverityRowID = SeverityRowID;
                ViewBag.ColorCode = ColorCode;
                ViewBag.SeverityGrid = SeverityGrid;

            }
            foreach (DataRow d in dt.Rows)
            {
                DataRow[] rowsFiltered = dbValue.Select("AntecedentRowID=" + d[0].ToString() + "and SubCheckRowID=" + d["SubCheckRowID"].ToString());
                if (rowsFiltered.Length > 0)
                {
                    if (d[4].ToString() == "textbox")
                    {
                        marksModel.Add(d[1].ToString(), rowsFiltered[0][1]);
                    }
                    else if (d[4].ToString() == "dropdown")
                    {
                        marksModel.Add(d[1].ToString() + "_" + rowsFiltered[0][1].ToString() + "_" + d[3].ToString(), rowsFiltered[0][1].ToString());
                    }
                    else if (d[4].ToString() == "checkbox")
                    {
                        marksModel.Add(d[1].ToString() + "_" + rowsFiltered[0][1].ToString(), rowsFiltered[0][1].ToString());
                    }
                    else if (d[4].ToString() == "fileUpload")
                        marksModel.Add(d[1].ToString(), d[0].ToString().ToString());

                }
                else
                {

                    if (d[4].ToString() == "textbox")
                    {
                        marksModel.Add(d[1].ToString(), "");
                    }
                    else if (d[4].ToString() == "dropdown")
                    {
                        marksModel.Add(d[1].ToString() + "_" + d[2].ToString() + "_" + d[3].ToString(), d[0].ToString());
                    }
                    else if (d[4].ToString() == "checkbox")
                    {
                        marksModel.Add(d[1].ToString() + "_" + d[2].ToString(), d[0].ToString());
                    }
                    else
                        marksModel.Add(d[1].ToString(), d[0].ToString());
                }
            }
            ViewBag.PersonalRowid = id.ToString();
            ViewBag.SubCheckId = SubCheckIds.ToString();
            ViewBag.clientRowId = ClientRowID.ToString();
            ViewBag.CheckStatusid = CaseStatus.ToString();
            ViewBag.ReportComment = ReportComment.ToString();
            ViewBag.version = version;
            TempData["SuccessMsg"] = "";
            return View(marksModel);
        }

        [HttpPost, ValidateInput(false)]
        [SessionExpireFilterAttribute]
        [ValidateAntiForgeryToken]
        public ActionResult UpdateAllChecksDetails(FormCollection formCollection, string action = "")
        {
            dynamic expando = new ExpandoObject();
            int PersonalRowid = Convert.ToInt32(formCollection["PersonalRowid"].ToString());
            var SubCheckid = Convert.ToString(formCollection["SubCheckId"]);
            short clientRowid = Convert.ToInt16(formCollection["clientRowId"].ToString());
            ViewBag.CheckStatusid = formCollection["CheckStatusid"].ToString();
            ViewBag.version = formCollection["version"].ToString();
            string Remarks = "";//formCollection["Remarks"].ToString();
            string ReportComment = "";
            string CheckStatus = action;
            ViewBag.ErrorMsg = "";
            //string ColorName = formCollection["ColorsName"].ToString();
            var marksModel = expando as IDictionary<string, object>;
            try
            {
                if (ModelState.IsValid)
                {

                    ClientCustomize cc = new ClientCustomize();
                    if (clientRowid > 0 && SubCheckid != "")
                    {
                        OperationViewModel cd = new OperationViewModel();
                        cd.PersonalRowID = PersonalRowid;
                        cd.clientRowId = clientRowid;
                        cd.CreatedBy = Convert.ToInt16(Session["TeamMemberRowID"]);
                        cd.moduleName = "ReportQC";

                        ClientCustomize bl = new ClientCustomize();
                        DataTable dt = new DataTable();
                        dt = bl.Antecedents_client_select_form_ALLNew(SubCheckid, clientRowid.ToString(), PersonalRowid);

                        foreach (DataRow d in dt.Rows)
                        {
                            string[] FString = d[1].ToString().Split('_');

                            if (d[4].ToString() == "textbox")
                            {
                                foreach (string key in formCollection.AllKeys)
                                {
                                    if (key == d[7].ToString())
                                    {
                                        marksModel.Add(d[1].ToString(), formCollection["1_" + key].ToString() + "_" + formCollection[key].ToString());
                                        cd.AntecedentRowID = Int64.Parse(d[0].ToString());
                                        if (formCollection[key].ToString() == "")
                                        {
                                            // ViewBag.ErrorMsg += FString[0] + ": " + FString[2];
                                            ViewBag.ErrorMsg = "";
                                        }
                                        break;
                                    }
                                }
                            }
                        }
                        // if (ViewBag.ErrorMsg != "")
                        //{
                        marksModel.Clear();
                        foreach (DataRow d in dt.Rows)
                        {
                            string[] FString = d[1].ToString().Split('_');

                            if (d[4].ToString() == "textbox")
                            {
                                foreach (string key in formCollection.AllKeys)
                                {
                                    if (key == d[7].ToString())
                                    {
                                        marksModel.Add(d[1].ToString(), formCollection["1_" + key].ToString() + "_" + formCollection[key].ToString());
                                        cd.AntecedentRowID = Int64.Parse(d[0].ToString());
                                        cd.SubCheckRowID = Convert.ToInt32(d[5]);
                                        cd.DisplayName = FString[2];
                                        cd.RepQcValue = formCollection[key].ToString();
                                        cd.DataEntryValue = formCollection["1_" + key].ToString();

                                        if (cd.RepQcValue != "")
                                        {
                                            bl.tblDataEntry_ReportInsert(cd);
                                        }
                                        break;
                                    }
                                }

                            }

                        }

                        string[] SubCheck1 = SubCheckid.Split(',');

                        foreach (var item in SubCheck1)
                        {
                            if (item == "69" || item == "70" || item == "71" || item == "72")
                            {

                                var key = "true_" + item;
                                var value = formCollection[key];

                                if (value == "1")
                                {
                                    cc.UpdateClientUser1(PersonalRowid, item, 1);

                                    #region Save LogTransaction Details
                                    clsCommonMethods.AddPQLogTrasaction(PersonalRowid, "UpdateAllChecksDetail", CheckStatus, "Report Team Member", "ActiveCheckStatus");
                                    #endregion

                                    #region Case/Check Action History Save
                                    clsCommonMethods.AddCheckActionHistory(PersonalRowid, Convert.ToInt16(item), CheckStatus, "ActiveCheckStatus");
                                    #endregion
                                }
                                else
                                {
                                    cc.UpdateClientUser1(PersonalRowid, item, 0);

                                    #region Save LogTransaction Details
                                    clsCommonMethods.AddPQLogTrasaction(PersonalRowid, "UpdateEmploymentVerInfoByRWQC", CheckStatus, "Report Team Member", "Check Status NotApplicable");
                                    #endregion

                                    #region Case/Check Action History Save
                                    clsCommonMethods.AddCheckActionHistory(PersonalRowid, Convert.ToInt16(item), CheckStatus, "Check Status NotApplicable");
                                    #endregion
                                }

                            }
                        }
                        // }
                        //else
                        //  {
                        //ViewBag.ErrorMsg += " is mandatory Fields ";
                        //   ViewBag.ErrorMsg = "";
                        // }
                        string[] SubCheck = SubCheckid.Split(',');
                        int Length = SubCheck.Length;
                        for (int i = 0; i < Length; i++)
                        {
                            Remarks = formCollection["Remarks_" + SubCheck[i]].ToString();
                            if (i == 0)
                            {
                                ReportComment = Remarks + "_" + SubCheck[i];
                            }
                            else
                            {
                                ReportComment += "|" + Remarks + "_" + SubCheck[i];
                            }

                            if (Remarks != "")
                            {
                                cc.UpdateReportComments(PersonalRowid, Convert.ToInt32(SubCheck[i]), Remarks);
                            }

                        }

                    }
                    else
                    {
                        ViewBag.ErrorMsg = "Invlid Employment id and model!";
                    }
                }
            }
            catch (Exception Ex)
            {
                //ViewBag.ErrorMsg = Ex.Message;
                ViewBag.ErrorMsg = "Invalid parameter value";
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            ViewBag.PersonalRowid = PersonalRowid.ToString();
            ViewBag.SubCheckId = SubCheckid.ToString();
            ViewBag.clientRowId = clientRowid.ToString();
            ViewBag.ReportComment = ReportComment.ToString();
            if (ViewBag.ErrorMsg == "")
            {
                TempData["SuccessMsg"] = "Record Update Successfully!";
            }
            return RedirectToAction("UpdateAllChecksDetails", "ReportQC", new { id = PersonalRowid, CaseStatus = ViewBag.CheckStatusid, version = "new" });


        }

