        private bool ReportValication(string clientRowid, string filePath, string fileName, HttpPostedFileBase file)
        {
            ClientCustomize cc = new ClientCustomize();
            bool isTrueSelectedFile = false;
            DataTable dtVal = cc.GetReportUploadValidation(clientRowid);
            if (dtVal.Rows.Count > 0)
            {
                string val = dtVal.Rows[0]["ReportValidation"].ToString();
                if (val == "True")
                {
                    StringBuilder text = new StringBuilder();
                    //PdfReader readers = new PdfReader(filePath);
                    PdfReader readers = new PdfReader(file.InputStream);
                    for (int page = 1; page <= 2; page++)
                    {
                        ITextExtractionStrategy strategy = new SimpleTextExtractionStrategy();
                        text.Append(PdfTextExtractor.GetTextFromPage(readers, page, strategy));
                    }

                    string[] aryContent = text.ToString().Split(' ');
                    if (text.ToString().Trim().Length > 0)
                    {
                        string filename1 = fileName.Replace(".pdf", "");
                        for (int i = 0; i < aryContent.Length; i++)
                        {

                            if (aryContent[i].Replace("\n", "").Contains(filename1))
                            {
                                isTrueSelectedFile = true;
                                break;
                            }





                        }
                        if (isTrueSelectedFile == false)
                        {
                            string[] a = fileName.Split('-');
                            for (int i = 0; i < aryContent.Length; i++)
                            {

                                if (aryContent[i].Replace("\n", "").Contains(a[0].ToString().Trim()))
                                {
                                    isTrueSelectedFile = true;
                                    break;
                                }





                            }

                        }
                    }
                    else
                    {
                        isTrueSelectedFile = true;
                    }
                }
                else
                {
                    isTrueSelectedFile = true;
                }

            }
            return isTrueSelectedFile;
        }

