        public ActionResult ManageLTIInterimRequest(int page = 1, string sort = "", string sortDir = "asc", string Search = "", string CaseStatus = "", string version = "New", short ClientRowID = 0, short AllocateTL = 0, string PersonalIds = "", byte tatHours = 0)
        {
            PQPersonalReportQCListPagedModel model = new PQPersonalReportQCListPagedModel();
            short teamMemberId = Convert.ToInt16(Session["TeamMemberRowID"]);
            try
            {
                if (AllocateTL > 0 && !string.IsNullOrEmpty(PersonalIds))
                {
                    byte UnAllocatedCount = 0;
                    string[] PerIDs = PersonalIds.Split(',').Select(str => str).ToArray();
                    ReportQCAllocationViewModel personalmodel = new ReportQCAllocationViewModel();
                    personalmodel.ModifiedBy = teamMemberId;
                    personalmodel.ModifiedDate = DateTime.Now;
                    personalmodel.CheckStatus = "Allocated-TL";
                    personalmodel.RWQCTeamMemberBy = AllocateTL;
                    personalmodel.RWQCTeamMemberDate = DateTime.Now;
                    foreach (var item in PerIDs)
                    {

                        string[] A = item.Split('-');
                        personalmodel.PersonalRowID = Convert.ToInt32(A[0]);
                        personalmodel.SubCheckRowID = Convert.ToInt32(A[1]);
                        short ClientID = repoPQPersonal.GetClientDetailsByPersonalId(personalmodel.PersonalRowID);
                        bool result = repoPQClientTMember.IsClientDepartTeamMembersExist(ClientID, personalmodel.RWQCTeamMemberBy, "Quality Check", "Team Leader Quality Check");
                        ClientCustomize cc = new ClientCustomize();
                        if (result)
                        {
                            cc.UpdatePersonalTableinfo(personalmodel.CheckStatus, personalmodel.RWQCTeamMemberBy, personalmodel.PersonalRowID);
                            //repoReportQC.UpdateAllocationForRWQCTLByRWQCManager(personalmodel);

                            if (CaseStatus == "LTIInterimRequest")
                            {
                                cc.UpdateLTIInterimRequest(personalmodel.PersonalRowID, AllocateTL, "AllocateTOTL", personalmodel.SubCheckRowID);

                            }

                            #region Save LogTransaction Details
                            clsCommonMethods.AddPQLogTrasaction(personalmodel.PersonalRowID, "ManageAllCandidateListForReportQC", "Allocated-ReportQC-TL", "Allocate TO TL", "Update");
                            #endregion

                            #region Case Action history save
                            clsCommonMethods.AddCaseActionHistory(personalmodel.PersonalRowID, "Allocated-RWQC-TL", "Allocated To RWQCTL");
                            #endregion
                        }
                        else
                        {
                            UnAllocatedCount++;
                        }
                    }
                }

                int pageSize = clsGlobalCommon.PageSize;
                string Statusid = "";


                if (version == "New")
                {
                    if (CaseStatus == "InterimRequest" || CaseStatus == "LTIInterimRequest")
                    {

                        model = repoReportQC.InterimRequest(page, pageSize, sort.ToLower(), sortDir.ToLower(), Search, Statusid, teamMemberId, ClientRowID, tatHours, CaseStatus);

                    }

                }


            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }

            //BindClientList();
            BindClientListBaseOnLogin(teamMemberId);
            GetTLMemberForAllocation();
            return View(model);
        }

