        [HttpGet]
        public ActionResult MISExportRWQC()
        {
            string Designation = Session["Designation"].ToString();
            List<MISExport> mISExport = new List<MISExport>();
            ClientCustomize cc = new ClientCustomize();
            if (Designation == "Manager Quality Check")
            {
                DataTable dt = new DataTable();
                dt = cc.MIS_TAT_ReportWriting();

                ViewBag.record = dt.Rows.Count;
                foreach (DataRow dr in dt.Rows)
                {
                    mISExport.Add(
                        new MISExport
                        {
                            TMFirstName = dr["TMFirstName"].ToString(),
                            YTR = dr["YTR"].ToString(),
                            Rejection = dr["Rejection"].ToString(),
                            Re_Verification = dr["Re_Verification"].ToString(),
                            Total_WIP = dr["Total_WIP"].ToString(),
                            Todays_Closure = dr["Todays_Closure"].ToString(),
                            Assigned_Today = dr["Assigned_Today"].ToString(),
                            Old_Assigned = dr["Old_Assigned"].ToString(),
                            Interim_Report = dr["Interim_Report"].ToString(),
                        }
                        );
                }





                ViewBag.Rejection = mISExport.Sum(T => Convert.ToInt32(T.Rejection));
                ViewBag.YTR = mISExport.Sum(T => Convert.ToInt32(T.YTR));
                ViewBag.Re_Verification = mISExport.Sum(T => Convert.ToInt32(T.Re_Verification));
                ViewBag.Total_WIP = mISExport.Sum(T => Convert.ToInt32(T.Total_WIP));
                ViewBag.Todays_Closure = mISExport.Sum(T => Convert.ToInt32(T.Todays_Closure));
                ViewBag.Assigned_Today = mISExport.Sum(T => Convert.ToInt32(T.Assigned_Today));
                ViewBag.Old_Assigned = mISExport.Sum(T => Convert.ToInt32(T.Old_Assigned));
                ViewBag.Interim_Report = mISExport.Sum(T => Convert.ToInt32(T.Interim_Report));
            }



            return View(mISExport);
        }

