        #region Compress ArtefactPDFTo Image
        [HttpGet]
        public ActionResult CompressArtefactPDFToImage()
        {
            return View();
        }
        [HttpPost]
        public ActionResult CompressArtefactPDFToImage(FormCollection formCollection, CompressimageViewModel model, HttpPostedFileBase file)
        {
            string result = "";
            string zipPath = "";
            string newFile = "";
            string StrFile = "";
            if (model.UploadDoc != null && model.UploadDoc.ContentLength > 0)
            {
                //string FolderPath = ConfigurationManager.AppSettings["CompressImage"];
                //string FolderPath1 = ConfigurationManager.AppSettings["CompressUrlImage"];
                string UplodFile = ConfigurationManager.AppSettings["UplodFile"].ToString();
                newFile = DateTime.Now.ToString("yyyyMMddHHmmss") + "_" + model.UploadDoc.FileName.ToString();
                string Paths = System.IO.Path.Combine(model.UploadDoc.FileName);
                string filePath = System.IO.Path.Combine(UplodFile, System.IO.Path.GetFileName(model.UploadDoc.FileName));
                string CompressOriginalArtefact = ConfigurationManager.AppSettings["CompressOriginalArtefactPDFToImage"].ToString();
                string CompressArtefactPDFToImage = ConfigurationManager.AppSettings["CompressArtefactPDFToImage"].ToString();
                string CompressZipArtefactPDFToImage = ConfigurationManager.AppSettings["CompressZipArtefactPDFToImage"].ToString();
                string[] strdata = newFile.Split('.');
                string filename = strdata[0].ToString();
                filePath = CompressOriginalArtefact + filename + "/";
                bool exists = System.IO.Directory.Exists(filePath);
                if (!exists)
                    System.IO.Directory.CreateDirectory(filePath);
                model.UploadDoc.SaveAs(UplodFile + newFile);

                if (model.UploadDoc != null && model.UploadDoc.ContentLength > 0)
                {
                    if (newFile.Contains(".pdf"))
                    {
                        SautinSoft.PdfFocus f = new SautinSoft.PdfFocus();
                        f.Serial = "80027423579"; //License for server 
                                                  //f.Serial = "10273316474"; //License for development machine
                        f.OpenPdf(UplodFile + newFile);

                        if (f.PageCount > 0)
                        {
                            string FileExtName = "";
                            string jpgFileName = newFile.Replace(".pdf", "");
                            string ImageName = string.Empty;
                            for (int i = 1; i <= f.PageCount; i++)
                            {
                                //FileExtName = ".jpg,";
                                ImageName += jpgFileName + i + FileExtName;
                                //string Savefile = FolderPath + ImageName;
                                //model.UploadDoc.SaveAs(Savefile);
                            }
                            if (!string.IsNullOrEmpty(ImageName) && ImageName.Length > 0)
                            {
                                ImageName = ImageName.Substring(0, ImageName.Length - 1);
                                f.ImageOptions.ImageFormat = System.Drawing.Imaging.ImageFormat.Jpeg;
                                f.ImageOptions.Dpi = 200;
                                f.ToImage(filePath, ImageName);
                            }
                            CompressArtefactPDFToImage = CompressArtefactPDFToImage + filename + "/";
                            exists = System.IO.Directory.Exists(CompressArtefactPDFToImage);
                            if (!exists)
                                System.IO.Directory.CreateDirectory(CompressArtefactPDFToImage);
                            for (int i = 1; i <= f.PageCount; i++)
                            {

                                CompressImage.Compressimage(filePath, CompressArtefactPDFToImage, jpgFileName + i + ".jpg");
                            }
                            string startPath = CompressArtefactPDFToImage;
                            StrFile = filename + ".zip";
                            zipPath = CompressZipArtefactPDFToImage + "/" + StrFile;
                            System.IO.Compression.ZipFile.CreateFromDirectory(startPath, zipPath);
                            try
                            {
                                System.IO.DirectoryInfo di = new DirectoryInfo(filePath);
                                foreach (FileInfo files in di.GetFiles())
                                {
                                    files.Delete();
                                }
                                foreach (DirectoryInfo dir in di.GetDirectories())
                                {
                                    dir.Delete(true);
                                }
                            }
                            catch (Exception ex)
                            {

                            }
                            try
                            {
                                System.IO.DirectoryInfo di = new DirectoryInfo(CompressArtefactPDFToImage);
                                foreach (FileInfo files in di.GetFiles())
                                {
                                    files.Delete();
                                }
                                foreach (DirectoryInfo dir in di.GetDirectories())
                                {
                                    dir.Delete(true);
                                }
                            }
                            catch (Exception ex)
                            {

                            }

                        }
                    }
                    else
                    {
                        CompressArtefactPDFToImage = CompressArtefactPDFToImage + filename + "/";
                        exists = System.IO.Directory.Exists(CompressArtefactPDFToImage);
                        if (!exists)
                            System.IO.Directory.CreateDirectory(CompressArtefactPDFToImage);
                        CompressImage.Compressimage(UplodFile, CompressArtefactPDFToImage, newFile);
                        string startPath = CompressArtefactPDFToImage;
                        StrFile = filename + ".zip";
                        zipPath = CompressZipArtefactPDFToImage + "/" + StrFile;
                        System.IO.Compression.ZipFile.CreateFromDirectory(startPath, zipPath);
                    }
                }
                else
                {
                    ViewBag.Error = "Plaese upload file";
                }
                //result = ImageResize.CompressImg(Server.MapPath(FolderPath + newFile), Server.MapPath(FolderPath), quality, Width, Height);
                string[] separators = { "::" };
                string[] result2 = result.Split(separators, 2, StringSplitOptions.None);
                ViewBag.Path = zipPath;
                ViewBag.Image = StrFile;
                ViewBag.Error = "Image Compress Successfully .";
            }
            return View();
        }
        [HttpGet]
        public ActionResult DownloadZip(string zipPath, string Filename)
        {
            var filePath = System.IO.Path.Combine(Directory.GetCurrentDirectory(), zipPath);
            var fileBytes = System.IO.File.ReadAllBytes(filePath);
            return File(fileBytes, "application/zip", Filename);
        }
