            {
                ClientCustomize cc = new ClientCustomize();

                foreach (var check in updatedChecks)
                {
                    if (check.BgcStatus != null && check.BgcStatus != "")
                    {
                        cc.UpdateExecutiveSummaryTcs(check.PersonalRowID, check.SubCheckID, check.TypeOfCheck, check.BgcStatus);
                    }
                }

            }
