        [HttpPost]
        public JsonResult UpdateCriminalResultSet(List<CriminalCourtVerificationVM> data)
        {
            try
            {
                if (data == null || data.Count == 0)
                {
                    return Json(new
                    {
                        Success = false,
                        Message = "No data received."
                    });
                }

                var recordFoundData = data.Where(x => x != null && !string.IsNullOrWhiteSpace(x.Status)).ToList();

                if (recordFoundData.Count == 0)
                {
                    return Json(new
                    {
                        Success = false,
                        Message = "No Record Found entry selected."
                    });
                }

                ClientCustomize cc = new ClientCustomize();

                foreach (var item in recordFoundData)
                {
                    cc.UpdateCriminalResultTcs(item.PersonalRowID, item.SubCheckRowID,item.TypeOfCheck, item.CourtType, item.Status, item.Remarks ?? string.Empty);
                }

                return Json(new
                {
                    Success = true,
                    Message = "Data saved successfully."
                });
            }
            catch (Exception ex)
            {
                return Json(new
                {
                    Success = false,
                    Message = ex.Message
                });
            }
        }


