                    //int SubCheckFamilyID = Convert.ToInt32(dr["SubCheckFamilyID"].ToString());
                    short ClientRowID = Convert.ToInt16(dr["ClientRowID"].ToString());
                    string companyrefno = (dr["Refno"].ToString());


                    string html = BulkRenderViewToString(ControllerContext, "~/views/ReportQC/BulkClientReport.cshtml", PersonalRowID, ClientRowID, true);
                    string IronKey = System.Configuration.ConfigurationManager.AppSettings["IronKey"].ToString();
                    var Renderer = new IronPdf.HtmlToPdf();
                    IronPdf.License.LicenseKey = IronKey;
                    //IronPdf.License.LicenseKey = "IRONPDF-MYLICENSE-KEY-1EF01";
                    Renderer.RenderingOptions.PaperSize = IronPdf.Rendering.PdfPaperSize.A4Extra;
                    Renderer.RenderingOptions.MarginTop = 3;
