        public JsonResult SendMailInsuffClear(int personalRowid = 0, short SubCheckRowID = 0, short ClientRowID = 0, int CheckRowID = 0, short CheckFamilyRowID = 0, int clientuserRowId = 0, int CheckStatusId = 0, string candcheckrowid = "")
        {

            bool result = false;
            string Remark = "";
            string insuffType = "";
            try
            {
                ClientCustomize cc = new ClientCustomize();
                clsSendMail mail = new clsSendMail();
                DataTable dt = new DataTable();
                //int ClientRowID = 2;
                string SpocName = string.Empty;
                string ClientName = string.Empty;
                string PaymentReceivedDate = string.Empty;
                string AcknowledgementDate = string.Empty;
                string Followup1 = string.Empty;
                string Remarks = string.Empty;
                string ClientEmailId = string.Empty;
                string CandidateEmailId = string.Empty;
                string SpocEmailId = string.Empty;
                string bodySpocAndClient = string.Empty;
                string MailTemplateNameSpoc = string.Empty;
                string SpocAndClientMailSubject = string.Empty;
                string resultDetails = string.Empty;
                string MailSignature = string.Empty;
                string DisplayName = string.Empty;
                List<Attachment> attachmentList = new List<Attachment>();
                string AnnexureInvoicingDocuments = string.Empty;
                string AnnexurApprovedDocuments = string.Empty;
                string InvoiceDocuments = string.Empty;
                string additionalEmailInsuff = string.Empty;


                if (personalRowid > 0)
                {
                    //dt = cc.SendMailAnnexureInvoiceDetailsBasedonId(id, ReminderSendOption);
                    DataSet ds = new DataSet();
                    //ds = cc.getAlertMailingDataForInsuff(personalRowid, SubCheckRowID);
                    var personalData = repoPQPersonal.GetCheckOrPersonalDetailsForSendMailByIdNew(CheckFamilyRowID, SubCheckRowID, personalRowid, CheckStatusId);

                    CandidateEmailId = Convert.ToString(personalData.EmailID);
                    SpocEmailId = Convert.ToString(personalData.SpocEmailID);
                    additionalEmailInsuff = System.Configuration.ConfigurationManager.AppSettings["additionalEmailInsuff"].ToString();
                    if (!string.IsNullOrEmpty(additionalEmailInsuff))
                    {
                        SpocEmailId = SpocEmailId + ',' + additionalEmailInsuff;
                    }
                    ClientEmailId = SpocEmailId; //Convert.ToString(personalData.SpocEmailID);
                    var templateDBSpocAndClient = cc.getMailtemplateforAnnexureInvoicing(ClientRowID, "Insuff", 0, 1, "Insufficiency");
                    var signature = mail.GetCompanyMailSignature();
                    MailSignature = string.Concat(MailSignature, "<b>", "",
                                                "</b><br/><b>E-mail id </b>: <a style='color:#df012a;' href='mailto:", "bgv.helpdesk@securitas-india.com", "'>", "bgv.helpdesk@securitas-india.com", "</a>");

                    string pathOfImageContent = ConfigurationManager.AppSettings["mailimages"].ToString();

                    LinkedResource LRsecuritaslogo = new LinkedResource(Server.MapPath(pathOfImageContent) + "Securitas-logo.png", MediaTypeNames.Image.Jpeg);
                    LRsecuritaslogo.ContentId = Guid.NewGuid().ToString();
                    string securitaslogo = @"<img src='cid:" + LRsecuritaslogo.ContentId + @"' width='25%'/>";
                    string UrlLinkInsuffClear = "";
                    if (templateDBSpocAndClient.Rows.Count > 0)
                    {
                        bodySpocAndClient = Convert.ToString(templateDBSpocAndClient.Rows[0]["MailTemplate"]);
                        bodySpocAndClient = bodySpocAndClient.Replace("{FCandidateName}", personalData.CandidateName);
                        bodySpocAndClient = bodySpocAndClient.Replace("{FCheckName}", personalData.SubCheckName);
                        bodySpocAndClient = bodySpocAndClient.Replace("{Verificationsource}", personalData.Verificationsource);
                        bodySpocAndClient = bodySpocAndClient.Replace("{FClientRefId}", personalData.ClientRefID);
                        bodySpocAndClient = bodySpocAndClient.Replace("{FReferenceID}", personalData.CompanyRefNo);
                        bodySpocAndClient = bodySpocAndClient.Replace("{FInsuffRemarks}", personalData.Remarks);
                        bodySpocAndClient = bodySpocAndClient.Replace("{FLocationName}", personalData.locationName);
                        bodySpocAndClient = bodySpocAndClient.Replace("{FInsuffRemarks}", Remarks);
                        bodySpocAndClient = bodySpocAndClient.Replace("{insuffType}", insuffType);
                        bodySpocAndClient = bodySpocAndClient.Replace("{MailSignature}", MailSignature);
                        bodySpocAndClient = bodySpocAndClient.Replace("{securitas-logo}", securitaslogo);

                        string ClientRowIdInsuffClear = clsCommonMethods.PEncrypt(personalData.ClientRowID.ToString());
                        string ChFamilRowIdInsuffClear = clsCommonMethods.PEncrypt(personalData.CheckFamilyRowID.ToString());
                        string subCheckIdInsuffClear = clsCommonMethods.PEncrypt(personalData.SubCheckRowID.ToString());
                        string PersonalRowIDInsuffClear = clsCommonMethods.PEncrypt(personalData.PersonalRowID.ToString());
                        string actionFrom = clsCommonMethods.PEncrypt("PendingInsuffBucket");
                        UrlLinkInsuffClear = "https://bgv.securitas-india.com/account/InsufficiencyClearByClient/?ClientRowId=" + ClientRowIdInsuffClear + "&ChFamilRowId=" + ChFamilRowIdInsuffClear + "&subCheckId=" + subCheckIdInsuffClear + "&PersonalRowID=" + PersonalRowIDInsuffClear + "&actionFrom=" + actionFrom;
                        bodySpocAndClient = bodySpocAndClient.Replace("{DBInsuffLink}", UrlLinkInsuffClear);

                        AlternateView alternateView = AlternateView.CreateAlternateViewFromString(bodySpocAndClient, null, MediaTypeNames.Text.Html);
                        alternateView.LinkedResources.Add(LRsecuritaslogo);

                        MailTemplateNameSpoc = Convert.ToString(templateDBSpocAndClient.Rows[0]["TemplateName"]);
                        SpocAndClientMailSubject = "Insufficiency " + Convert.ToString(personalData.CandidateName) + "  " + Convert.ToString(personalData.SubCheckName) + " ( " + candcheckrowid + " ) ";

                        //result = mail.AnnexureInvoicingSendMail("Insuff Rasied has been successfully!!! ", "bgv.request@securitas-india.com", CandidateEmailId, SpocEmailId, ClientEmailId, SpocAndClientMailSubject, bodySpocAndClient, attachmentList, alternateView);
                        result = mail.InsuffSupportSendMail("Insuff Rasied has been successfully!!! ", "insuff.support@securitas-india.com", CandidateEmailId, SpocEmailId, ClientEmailId, SpocAndClientMailSubject, bodySpocAndClient, attachmentList, alternateView);
                        if (result == true)
                        {
                            resultDetails = "Mail has been Sent successfully!!!";
                            // Save Candidate mail of Insuff Raised for Reminder for clear insuff
                            cc.saveCandidatemail(personalData.PersonalRowID, "Insuff mail", personalData.EmailID, SpocEmailId, SpocAndClientMailSubject, bodySpocAndClient, ClientRowID, 1, personalData.SubCheckRowID);
                        }
                        else
                        {
                            resultDetails = "Mail don't Sent!!";
                        }
                    }
                }
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            return Json(new { result }, JsonRequestBehavior.AllowGet);
        }

