        public void GetframeFromVideo(int PersonalRowId, int SubCheckRowId, string inputVideo, string outputImage, string fileName)
        {
            string ffmpegPath = "D:\\wwwroot2\\Emailers\\ffmpeg.exe";

            // Example: frame #5 at 30 fps ≈ 0.166s

            double fps = 30.0;  // adjust if your video has a different FPS
            int frameNumber = 5;
            double timestamp = frameNumber / fps;
            string arguments = $"-ss 0 -i \"{inputVideo}\" -vframes 1 -q:v 2 \"{outputImage}\"";
            // string arguments = $"-ss {timestamp.ToString(CultureInfo.InvariantCulture)} -i \"{inputVideo}\" -vframes 1 -q:v 2 \"{outputImage}\"";
            // FFmpeg arguments: fast seek, grab one frame
            //string arguments = $"-ss {timestamp.ToString(CultureInfo.InvariantCulture)} -i \"{inputVideo}\" -vframes 1 -q:v 2 \"{outputImage}\"";

            try

            {
                var process = new Process
                {
                    StartInfo = new ProcessStartInfo
                    {
                        FileName = ffmpegPath,
                        Arguments = arguments,
                        RedirectStandardError = true,
                        RedirectStandardOutput = true,
                        UseShellExecute = false,
                        CreateNoWindow = true
                    },

                    EnableRaisingEvents = true
                };

                process.OutputDataReceived += (s, e) =>
                {
                    if (!string.IsNullOrEmpty(e.Data))
                        Console.WriteLine("FFmpeg out: " + e.Data);
                };
                process.ErrorDataReceived += (s, e) =>
                {
                    if (!string.IsNullOrEmpty(e.Data))
                        Console.WriteLine("FFmpeg err: " + e.Data);
                };
                process.Exited += (s, e) =>
                {
                    Console.WriteLine("✅ FFmpeg process ended.");
                };

                process.Start();

                process.BeginOutputReadLine();

                process.BeginErrorReadLine();

                // no WaitForExit here → program continues immediately

                // Console.WriteLine("▶ FFmpeg started, program continues...");

                SavePQVerifiedUploadDocSelfie(PersonalRowId, Convert.ToInt16(SubCheckRowId), "Verified", "CandidateSelfie", "provideddocuments", "Candidate Selfie", fileName);

            }

            catch (Exception Ex)
            {

                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);


            }

        }

