        public class HtmlRequest
        {
            public string HtmlContent { get; set; }
        }


        [HttpPost]
        public ActionResult GenerateWordFromHtmlSA1()
        {
            Request.InputStream.Position = 0;
            string jsonData = new StreamReader(Request.InputStream).ReadToEnd();

            var request = JsonConvert.DeserializeObject<HtmlRequest>(jsonData);
            string htmlContent = request.HtmlContent;

            byte[] bytes = System.Text.Encoding.UTF8.GetBytes(htmlContent);

            return File(bytes,
                "application/msword",
                "Report_" + DateTime.Now.ToString("yyyyMMdd") + ".doc");
        }

        [HttpPost]
        public ActionResult GenerateWordFromHtmlSA2(HtmlRequest request)
        {
            try
            {
                if (request == null || string.IsNullOrWhiteSpace(request.HtmlContent))
                {
                    return new HttpStatusCodeResult(400, "HTML content is empty");
                }

                string htmlContent = ConvertImagesToBase64(request.HtmlContent);

                // Word-compatible HTML wrapper
                string wordHeader = "<html xmlns:o='urn:schemas-microsoft-com:office:office' " +
                                  "xmlns:w='urn:schemas-microsoft-com:office:word' " +
                                  "xmlns='http://www.w3.org/TR/REC-html40'>";

                string fullHtml = wordHeader + htmlContent + "</html>";

                byte[] bytes = System.Text.Encoding.UTF8.GetBytes(fullHtml);

                return File(bytes,
                           "application/msword",
                           "Report_" + DateTime.Now.ToString("yyyyMMdd") + ".doc");
            }
            catch (Exception ex)
            {
                // Log exception here if needed
                return new HttpStatusCodeResult(500, "Error generating Word document");
            }
        }

        public string ConvertImagesToBase64(string html)
        {
            var imgTags = Regex.Matches(html, "<img[^>]+src=[\"']([^\"']+)[\"'][^>]*>");
            foreach (Match match in imgTags)
            {
                string imgTag = match.Value;
                string imgSrc = match.Groups[1].Value;
                // Skip if already base64
                if (imgSrc.StartsWith("data:image"))
                    continue;
                try
                {
                    string path = "";
                    // Handle relative path
                    if (imgSrc.StartsWith("/"))
                    {
                        path = HttpContext.Server.MapPath(imgSrc);
                    }
                    else
                    {
                        continue; // skip external URLs (optional)
                    }
                    if (System.IO.File.Exists(path))
                    {
                        byte[] bytes = System.IO.File.ReadAllBytes(path);
                        string base64 = Convert.ToBase64String(bytes);
                        string extension = System.IO.Path.GetExtension(path).Replace(".", "");
                        string newImgSrc = $"data:image/{extension};base64,{base64}";
                        html = html.Replace(imgSrc, newImgSrc);
                    }
                }
                catch { }
            }
            return html;
        }


        [HttpGet]
        public ActionResult GetRiskMatrix(int id, int ClientRowID)
        {
            var model = new RiskMatrixModel();
            model.PersonalRowId = id;
            model.ClientRowId = ClientRowID;

            DataTable dt = new DataTable();
            DataTable dt1 = new DataTable();
            ClientCustomize cc = new ClientCustomize();

            dt = cc.SP_GetRiskMatrix(model.PersonalRowId);
            model.Items = new List<RiskMatrixItem>();

            if (dt.Rows.Count > 0)
            {
                foreach (DataRow dr in dt.Rows)
                {

                    var riskType = dr["RiskTYpe"].ToString().Trim();
                    var riskFactor = dr["RiskFactor"].ToString();

                    if (!riskType.Equals("Observation", StringComparison.OrdinalIgnoreCase))
                    {
                        model.Items.Add(new RiskMatrixItem
                        {
                            RiskFactor = dr["RiskFactor"].ToString(),
                            Likelihood = Convert.ToInt32(dr["Likelihood"]),
                            Impact = Convert.ToInt32(dr["Impact"]),
                            RiskScore = Convert.ToInt32(dr["RiskScore"]),
                            Category = dr["Category"].ToString()
                        });
                    }


                    if (riskType.Equals("Observation", StringComparison.OrdinalIgnoreCase))
                    {
                        if (string.IsNullOrEmpty(model.Recommendations1))
                        {
                            model.Recommendations1 = riskFactor;
                        }
                        else
                        {
                            model.Recommendations1 += ", " + riskFactor;
                        }
                    }

                }
            }
            else
            {
                for (int i = 0; i < 8; i++)
                {
                    model.Items.Add(new RiskMatrixItem());
                }
            }

            dt1 = cc.SP_GetRiskMatrixConsolidated(model.PersonalRowId);
            model.ConsolodatedItems = new List<RiskMatrixConsolidatedItem>();

            if (dt1.Rows.Count > 0)
            {
                foreach (DataRow dr in dt1.Rows)
                {
                    model.ConsolodatedItems.Add(new RiskMatrixConsolidatedItem
                    {
                        Level = dr["Level"].ToString(),
                        Status = dr["Status"].ToString(),
                        Remarks = dr["Remarks"].ToString(),
                    });
                }
            }
            else
            {
                for (int i = 0; i < 4; i++)
                {
                    model.ConsolodatedItems.Add(new RiskMatrixConsolidatedItem());
                }
            }

            return PartialView("_RiskMatrixForm", model);
        }


        [HttpPost]
        [ValidateInput(false)]
        public ActionResult SubmitRiskMatrix(RiskMatrixModel model)
        {
            if (!ModelState.IsValid)
            {
                return PartialView("_RiskMatrixForm", model);
            }

            try
            {
                var recomendation = model.Recommendations1;

                ClientCustomize cc = new ClientCustomize();

                foreach (var item in model.Items)
                {
                    RiskMatrixViewModel vm = new RiskMatrixViewModel
                    {
                        PersonalRowID = model.PersonalRowId,
                        ClientRowID = model.ClientRowId,
                        RiskFactor = item.RiskFactor,
                        Likelihood = item.Likelihood,
                        Impact = item.Impact,
                        RiskScore = item.RiskScore,
                        Category = item.Category,
                        RiskType = "Risk Factor"
                    };

                    cc.InsertRiskMatrix(vm);
                }

                foreach (var item in model.ConsolodatedItems)
                {
                    RiskMatrixConsolidatedItem vm1 = new RiskMatrixConsolidatedItem
                    {
                        PersonalRowID = model.PersonalRowId,
                        ClientRowID = model.ClientRowId,
                        Level = item.Level,
                        Status = item.Status,
                        Remarks = item.Remarks
                    };

                    cc.InsertRiskMatrixConsolidated(vm1);
                }
                if (recomendation != null)
                {
                    cc.InsertRiskMatrixObservation(model.PersonalRowId, model.ClientRowId, recomendation, 0, 0, 0, "", "Observation");
                }

                ViewBag.SuccessMsg = "Risk Matrix Saved Successfully!";
            }
            catch (Exception ex)
            {
                ViewBag.Message = "Error: " + ex.Message;
            }

            return PartialView("_RiskMatrixForm", model);
        }

